import { cn } from '@heal/front-core/lib/utils';
import { TraceViewerActionBlock } from '@heal/front-core/ui';
import { FileTextIcon } from '@phosphor-icons/react';
import { useEffect, useRef } from 'react';

import { useDataProvider } from '../../../../context/data-provider/data-provider.hooks';
import { useStatementProvider } from '../../../../context/statement-provider/statement-provider.hooks';
import { useTriageVerdictForm } from '../../../../context/triage-verdict-form-provider/triage-verdict-form-provider.hooks';
import { Statement } from '../../../../types/test';
import { formatDuration } from '../../../../utils/format-duration';
import { EmptyState } from '../../_components/empty-state';
import { VerdictActionMenu } from '../../_components/verdict-action-menu';

import { mapStatementStatusToStepCardStatus } from './code-view';

export const ActionView = () => {
  const { currentTest } = useDataProvider();

  if (!currentTest) {
    return (
      <EmptyState
        icon={<FileTextIcon className="h-10 w-10" weight="thin" />}
        message="This test case has no content yet."
      />
    );
  }

  const statementsWithComments = currentTest.statements.filter((statement) =>
    hasComments(statement),
  );

  if (statementsWithComments.length === 0) {
    return (
      <EmptyState
        icon={<FileTextIcon className="h-10 w-10" weight="thin" />}
        message="This test case has no action items."
      />
    );
  }

  return (
    <div className="flex h-full flex-1 flex-col overflow-auto p-2">
      <div className="flex flex-1 flex-col gap-1.5 overflow-auto">
        {currentTest.statements.map((statement, index) => (
          <ActionItem
            key={statement.code}
            statement={statement}
            failingStatementIndex={index}
          />
        ))}
      </div>
    </div>
  );
};

function ActionItem({
  statement,
  failingStatementIndex,
  nestedLevel = 0,
}: {
  statement: Statement;
  /** 0-based index of this statement in the top-level list. */
  failingStatementIndex: number;
  nestedLevel?: number;
}) {
  const { activeStatement, setActiveStatementId, selectActiveStatement } =
    useStatementProvider();
  const { state } = useTriageVerdictForm();
  const ref = useRef<HTMLDivElement>(null);
  const isActive = activeStatement?.id === statement.id;
  const isActiveFormStep =
    state.isOpen &&
    state.selectedFailingStatementIndex === failingStatementIndex;

  useEffect(() => {
    if (isActive && ref.current) {
      ref.current.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    }
  }, [isActive]);

  if (!hasComments(statement)) {
    return null;
  }

  function handleSelectStatement() {
    if (activeStatement?.id === statement.id) {
      setActiveStatementId(null);

      return;
    }

    selectActiveStatement(statement.id);
  }

  return (
    <div
      ref={ref}
      className={cn(
        'flex flex-col gap-1.5',
        nestedLevel > 0 && 'ml-4 border-l-2 border-muted pl-3',
      )}
    >
      {!!statement.comment && (
        <VerdictActionMenu failingStatementIndex={failingStatementIndex}>
          <TraceViewerActionBlock
            key={statement.code}
            status={mapStatementStatusToStepCardStatus(statement.status)}
            duration={formatDuration(statement.durationMs)}
            selected={isActiveFormStep}
            active={activeStatement?.id === statement.id}
            onClick={handleSelectStatement}
            screenshotUrl={statement.screenshot ?? undefined}
            classNames={{
              root: 'group-hover/menu:bg-brand-subtle group-data-[state=open]/menu:bg-brand-subtle-hover',
            }}
            {...splitComment(statement.comment ?? '')}
          />
        </VerdictActionMenu>
      )}
      {statement.children.map((child) => (
        <ActionItem
          key={child.code}
          statement={child}
          failingStatementIndex={failingStatementIndex}
          nestedLevel={nestedLevel + 1}
        />
      ))}
    </div>
  );
}

const ACTION_VERBS = [
  'Navigate to',
  'Navigates to',
  'Click on',
  'Clicks on',
  'Click',
  'Clicks',
  'Fill in',
  'Fills in',
  'Fill',
  'Fills',
  'Type in',
  'Types in',
  'Type',
  'Types',
  'Wait for',
  'Waits for',
  'Select',
  'Selects',
  'Search for',
  'Searches for',
  'Submit',
  'Submits',
  'Scroll to',
  'Scrolls to',
  'Scroll',
  'Scrolls',
  'Upload',
  'Uploads',
  'Download',
  'Downloads',
  'Open',
  'Opens',
  'Close',
  'Closes',
  'Hover',
  'Hovers',
  'Check',
  'Checks',
  'Uncheck',
  'Unchecks',
  'Accept',
  'Accepts',
  'Dismiss',
  'Dismisses',
  'Verify',
  'Verifies',
  'Assert',
  'Asserts',
  'Expect',
  'Expects',
];

function splitComment(comment: string): { action: string; target: string } {
  const cleaned = comment.replace(/^-+\s*|\s*-+$/g, '').trim();

  const lowerCleaned = cleaned.toLowerCase();
  for (const verb of ACTION_VERBS) {
    if (lowerCleaned.startsWith(verb.toLowerCase() + ' ')) {
      return {
        action: verb,
        target: cleaned.slice(verb.length + 1),
      };
    }
  }

  const [action, ...rest] = cleaned.split(' ');

  return { action, target: rest.join(' ') };
}

function hasComments(statement: Statement): boolean {
  return (
    !!statement.comment ||
    statement.children.some((child) => hasComments(child))
  );
}
