/**
 * Per-user permissions the host app grants to the run-viewer. Each cap
 * defaults to `true` so that hosts opting out of explicit gating get the full
 * capability set; locked-down hosts override only what they need to disable.
 */
export interface TracerCapabilities {
  /** May submit a new verdict via the form. */
  canWriteTriagedVerdict: boolean;

  /** May transition a triaged verdict to a final verdict. */
  canWriteFinalVerdict: boolean;
}

/**
 * Per-environment feature toggles. Different host environments (online
 * tracer, offline viewer, embedded contexts) can disable whole panes
 * without forking the package. Defaults to all features enabled.
 */
export interface TracerFeatures {
  /** Verdict-form view (the right-hand pane in `mode='verdict'`). */
  verdictForm: boolean;
}

export const DEFAULT_TRACER_CAPABILITIES: TracerCapabilities = {
  canWriteTriagedVerdict: false,
  canWriteFinalVerdict: false,
};

export const DEFAULT_TRACER_FEATURES: TracerFeatures = {
  verdictForm: true,
};

export const withCapabilityDefaults = (
  override?: Partial<TracerCapabilities>,
): TracerCapabilities => ({
  ...DEFAULT_TRACER_CAPABILITIES,
  ...(override ?? {}),
});

export const withFeatureDefaults = (
  override?: Partial<TracerFeatures>,
): TracerFeatures => ({
  ...DEFAULT_TRACER_FEATURES,
  ...(override ?? {}),
});
