import {
  FormControl,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
  Textarea,
} from '@heal/front-core/ui';
import type { useForm } from 'react-hook-form';

import type {
  CreateTriageVerdictFormValues,
  FormType,
} from '../_lib/create-triage-verdict-form-schema';

interface TypeFieldsProps {
  formType: FormType;
  form: ReturnType<typeof useForm<CreateTriageVerdictFormValues>>;
}

export const TypeFields = ({ formType, form }: TypeFieldsProps) => {
  if (formType === 'bug') {
    return (
      <>
        <TextareaField
          form={form}
          name="expected"
          label="Expected"
          placeholder="Expected behavior"
        />
        <TextareaField
          form={form}
          name="actual"
          label="Actual"
          placeholder="Actual behavior"
        />
      </>
    );
  }
  if (formType === 'ui_changed') {
    return (
      <TextareaField
        form={form}
        name="description"
        placeholder="Describe the UI change"
      />
    );
  }
  if (formType === 'heal_system_issue') {
    return (
      <TextareaField
        form={form}
        name="description"
        label="Description"
        placeholder="Describe the infrastructure issue"
      />
    );
  }
  if (formType === 'unstable_locator') {
    return (
      <TextareaField
        form={form}
        name="description"
        label="Description and fix instructions"
        placeholder="How to make the locator stable"
      />
    );
  }
  if (formType === 'broken_test_logic') {
    return (
      <>
        <TextareaField
          form={form}
          name="reason"
          label="Reason"
          placeholder="Why is the test logic broken?"
        />
        <TextareaField
          form={form}
          name="suggestedFix"
          label="Suggested fix (optional)"
          placeholder="How to fix the test"
          minRows="sm"
        />
      </>
    );
  }

  return null;
};

interface TextareaFieldProps {
  form: ReturnType<typeof useForm<CreateTriageVerdictFormValues>>;
  name: keyof Omit<
    CreateTriageVerdictFormValues,
    'type' | 'failingStatementIndex'
  >;
  label?: string;
  placeholder: string;
  minRows?: 'sm' | 'md';
}

const TextareaField = ({
  form,
  name,
  label,
  placeholder,
  minRows = 'md',
}: TextareaFieldProps) => (
  <FormField
    control={form.control}
    name={name}
    render={({ field }) => (
      <FormItem>
        {label && <FormLabel className="text-xs">{label}</FormLabel>}
        <FormControl>
          <Textarea
            {...field}
            className={`${
              minRows === 'sm' ? 'min-h-[48px]' : 'min-h-[60px]'
            } border-border bg-background text-xs`}
            placeholder={placeholder}
          />
        </FormControl>
        <FormMessage />
      </FormItem>
    )}
  />
);
