import { useMemo } from 'react';

import {
  withCapabilityDefaults,
  withFeatureDefaults,
} from '../../types/capabilities';

import { CapabilitiesProviderContext } from './capabilities-provider.context';
import { CapabilitiesProviderProps } from './capabilities-provider.types';

export const CapabilitiesProvider = ({
  children,
  capabilities,
  features,
}: CapabilitiesProviderProps) => {
  const value = useMemo(
    () => ({
      capabilities: withCapabilityDefaults(capabilities),
      features: withFeatureDefaults(features),
    }),
    [capabilities, features],
  );

  return (
    <CapabilitiesProviderContext.Provider value={value}>
      {children}
    </CapabilitiesProviderContext.Provider>
  );
};
