import { useMemo } from 'react';

import { ExecutionProviderContext } from './execution-provider.context';
import {
  ExecutionProviderContextValue,
  ExecutionProviderProps,
} from './execution-provider.types';

const NO_OP = (): void => undefined;

export const ExecutionProvider = ({
  children,
  executions,
  currentExecutionId,
  onExecutionChange,
}: ExecutionProviderProps) => {
  const value = useMemo<ExecutionProviderContextValue>(
    () => ({
      executions: executions ?? [],
      currentExecutionId: currentExecutionId ?? null,
      onExecutionChange: onExecutionChange ?? NO_OP,
    }),
    [executions, currentExecutionId, onExecutionChange],
  );

  return (
    <ExecutionProviderContext.Provider value={value}>
      {children}
    </ExecutionProviderContext.Provider>
  );
};
