import { ChevronDownIcon, ChevronRightIcon } from 'lucide-react';

export interface TestListGroupHeaderProps {
  label: string;
  count: number;
  isOpen: boolean;
  onToggle: () => void;
}

export const TestListGroupHeader = ({
  label,
  count,
  isOpen,
  onToggle,
}: TestListGroupHeaderProps) => {
  return (
    <button
      type="button"
      onClick={onToggle}
      className="flex w-full items-center gap-1.5 px-3 py-1.5 text-xs font-medium text-muted-foreground hover:text-foreground"
    >
      {isOpen ? (
        <ChevronDownIcon className="size-3.5 shrink-0" />
      ) : (
        <ChevronRightIcon className="size-3.5 shrink-0" />
      )}
      <span className="truncate">{label}</span>
      <span className="ml-auto shrink-0 rounded-full bg-muted px-1.5 py-0.5 text-[10px] tabular-nums">
        {count}
      </span>
    </button>
  );
};
