// Thin wrapper around `@heal-dev/front-run-viewer`'s `<Tracer>` that
// feeds it from the local heal-playwright-tracer server (`/api/*`).
// Mirrors the structure of `apps/web/src/pages/tracer/tracer.tsx`.

import { Tracer } from '@heal-dev/front-run-viewer';
import type { Test, TestList } from '@heal-dev/front-run-viewer';
import { useEffect, useMemo, useState } from 'react';
import { BrowserRouter, useLocation, useNavigate } from 'react-router';

import {
  fetchExecutions,
  fetchIndex,
  fetchTrace,
  type ExecutionSummary,
} from './api';
import { AuthProvider, useAuth } from './lib/auth-context';
import { toTestList, toTracerTest } from './lib/map-trace';

export const App = () => (
  <AuthProvider>
    <BrowserRouter>
      <AppContent />
    </BrowserRouter>
  </AuthProvider>
);

const AppContent = () => {
  const [executions, setExecutions] = useState<ExecutionSummary[]>([]);
  const [executionsError, setExecutionsError] = useState<string | null>(null);
  const [testList, setTestList] = useState<TestList>([]);
  const [currentTest, setCurrentTest] = useState<Test | null>(null);
  const [indexError, setIndexError] = useState<string | null>(null);
  const [params, setParams] = useState<{
    executionId?: string;
    testId?: string;
    attemptNumber?: number;
  }>({});

  const { pathname } = useLocation();
  const navigate = useNavigate();
  const { state: authState, signIn } = useAuth();
  const isOnIndex = !pathname.includes('/executions/');

  // 1. List executions once on mount.
  useEffect(() => {
    let cancelled = false;
    fetchExecutions()
      .then((res) => {
        if (cancelled) return;
        setExecutions(res.executions);
      })
      .catch((err: Error) => {
        if (!cancelled) setExecutionsError(err.message);
      });

    return () => {
      cancelled = true;
    };
  }, []);

  // 2. Redirect to the latest execution when landing on the bare index.
  useEffect(() => {
    const firstId = executions[0]?.executionId;
    if (isOnIndex && firstId) {
      navigate(`/executions/${encodeURIComponent(firstId)}`, { replace: true });
    }
  }, [isOnIndex, executions, navigate]);

  // 3. Whenever the URL execution changes, refetch its index.
  useEffect(() => {
    if (!params.executionId) {
      setTestList([]);

      return;
    }
    let cancelled = false;
    setCurrentTest(null);
    setIndexError(null);
    fetchIndex(params.executionId)
      .then((res) => {
        if (cancelled || !params.executionId) return;
        setTestList(toTestList(params.executionId, res.tests));
      })
      .catch((err: Error) => {
        if (!cancelled) setIndexError(err.message);
      });

    return () => {
      cancelled = true;
    };
  }, [params.executionId]);

  // 4. Load the selected test's trace whenever the routing params change.
  useEffect(() => {
    if (!params.executionId || !params.testId || !params.attemptNumber) {
      setCurrentTest(null);

      return;
    }
    let cancelled = false;
    fetchTrace(params.executionId, params.testId, params.attemptNumber)
      .then((trace) => {
        if (cancelled || !params.testId) return;
        setCurrentTest(toTracerTest(trace, params.testId));
      })
      .catch(() => {
        if (!cancelled) {
          setCurrentTest(null);
        }
      });

    return () => {
      cancelled = true;
    };
  }, [params.executionId, params.testId, params.attemptNumber]);

  const tracerExecutions = useMemo(
    () =>
      executions.map((e) => ({
        id: e.executionId,
        startedAt: e.startedAt,
        totals: e.totals,
        git: e.git,
      })),
    [executions],
  );

  if (executionsError) {
    return (
      <div className="flex h-full w-full items-center justify-center p-8">
        <div className="max-w-md text-sm text-danger-solid">
          Failed to load executions: {executionsError}
        </div>
      </div>
    );
  }

  if (executions.length === 0) {
    return (
      <div className="flex h-full w-full items-center justify-center p-8">
        <div className="max-w-md text-sm text-muted-foreground">
          No executions found under <code>./heal-traces/</code>. Run your
          Playwright tests with the heal tracer wired up to populate this
          viewer.
        </div>
      </div>
    );
  }

  if (indexError) {
    return (
      <div className="flex h-full w-full items-center justify-center p-8">
        <div className="max-w-md text-sm text-danger-solid">
          Failed to load trace index: {indexError}
        </div>
      </div>
    );
  }

  return (
    <Tracer
      testList={testList}
      currentTest={currentTest}
      basePath=""
      onParamsChange={setParams}
      mode="default"
      features={{ showGroupBy: false, verdictForm: false }}
      executions={tracerExecutions}
      authSlot={{ state: authState, onSignIn: signIn }}
    />
  );
};
