import { useMemo } from 'react';

import { AuthSlotProviderContext } from './auth-slot-provider.context';
import type { AuthSlotProviderProps } from './auth-slot-provider.types';

export const AuthSlotProvider = ({
  children,
  authSlot,
}: AuthSlotProviderProps) => {
  const value = useMemo(() => authSlot ?? null, [authSlot]);

  return (
    <AuthSlotProviderContext.Provider value={value}>
      {children}
    </AuthSlotProviderContext.Provider>
  );
};
