import { createContext, useContext, useEffect, useState, type ReactNode } from 'react';

export interface AuthProfile {
  email: string;
  firstName?: string;
  lastName?: string;
  username?: string;
  organization?: { name: string; slug: string };
}

export type AuthState =
  | { status: 'loading' }
  | { status: 'not_installed' }
  | { status: 'logged_out' }
  | { status: 'logged_in'; profile: AuthProfile };

interface AuthContextValue {
  state: AuthState;
  signIn: () => void;
  refresh: () => Promise<void>;
}

const Ctx = createContext<AuthContextValue | null>(null);

export const useAuth = (): AuthContextValue => {
  const v = useContext(Ctx);
  if (!v) throw new Error('useAuth must be used inside <AuthProvider>');

  return v;
};

const POLL_MS = 250;
const WHOAMI_TIMEOUT_MS = 8_000;
const AUTH_URL_TIMEOUT_MS = 10_000;

interface JobSnapshot {
  status: 'running' | 'exited';
  exitCode: number | null;
  stdout: string[];
  stderr: string[];
}

class ExecForbidden extends Error {}

async function startExec(bin: string, args: string[]): Promise<string> {
  const res = await fetch('/api/exec', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ bin, args }),
  });
  if (res.status === 403) throw new ExecForbidden();
  if (!res.ok) throw new Error(`/api/exec ${res.status}`);
  const body = (await res.json()) as { jobId: string };

  return body.jobId;
}

async function pollJob(jobId: string): Promise<JobSnapshot> {
  const res = await fetch(`/api/exec/${jobId}`);
  if (!res.ok) throw new Error(`/api/exec/${jobId} ${res.status}`);

  return (await res.json()) as JobSnapshot;
}

function parseLastJsonLine(lines: string[]): Record<string, unknown> | null {
  for (let i = lines.length - 1; i >= 0; i--) {
    const t = lines[i].trim();
    if (!t.startsWith('{')) continue;
    try {
      return JSON.parse(t) as Record<string, unknown>;
    } catch {
      // keep scanning
    }
  }

  return null;
}

const wait = (ms: number): Promise<void> => new Promise((r) => setTimeout(r, ms));

async function fetchWhoami(): Promise<AuthState> {
  let jobId: string;
  try {
    jobId = await startExec('heal', ['whoami', '--json']);
  } catch (err) {
    if (err instanceof ExecForbidden) return { status: 'not_installed' };
    throw err;
  }

  const deadline = Date.now() + WHOAMI_TIMEOUT_MS;
  for (;;) {
    const snap = await pollJob(jobId);
    if (snap.status === 'exited') {
      if (snap.exitCode !== 0) return { status: 'not_installed' };
      const parsed = parseLastJsonLine(snap.stdout);
      if (parsed && parsed.loggedIn === false) return { status: 'logged_out' };
      if (parsed && typeof parsed.email === 'string') {
        return { status: 'logged_in', profile: parsed as unknown as AuthProfile };
      }

      return { status: 'logged_out' };
    }
    if (Date.now() > deadline) return { status: 'logged_out' };
    await wait(POLL_MS);
  }
}

async function startSignIn(): Promise<void> {
  const jobId = await startExec('heal', [
    'login',
    '--json',
    '--return-to',
    window.location.href,
  ]);

  const deadline = Date.now() + AUTH_URL_TIMEOUT_MS;
  for (;;) {
    const snap = await pollJob(jobId);
    for (const line of snap.stdout) {
      const t = line.trim();
      if (!t.startsWith('{')) continue;
      try {
        const obj = JSON.parse(t) as { event?: string; url?: string };
        if (obj.event === 'auth_url' && typeof obj.url === 'string') {
          window.location.href = obj.url;

          return;
        }
      } catch {
        /* ignore */
      }
    }
    if (snap.status === 'exited') throw new Error('heal login exited before emitting auth_url');
    if (Date.now() > deadline) throw new Error('Timed out waiting for auth URL');
    await wait(POLL_MS);
  }
}

export const AuthProvider = ({ children }: { children: ReactNode }) => {
  const [state, setState] = useState<AuthState>({ status: 'loading' });

  const refresh = async () => {
    try {
      setState(await fetchWhoami());
    } catch {
      setState({ status: 'logged_out' });
    }
  };

  useEffect(() => {
    void refresh();
  }, []);

  const signIn = () => {
    startSignIn().catch((err: Error) => {
      // eslint-disable-next-line no-console -- surfaced for users running the standalone viewer
      console.error('[heal] sign-in failed:', err.message);
    });
  };

  return <Ctx.Provider value={{ state, signIn, refresh }}>{children}</Ctx.Provider>;
};
