import type { ReactNode } from 'react';

import { cn } from '../../../../lib/utils';
import type {
  StepCardStatus,
  StepCardVariant,
  StepConfig,
  VerdictType,
} from '../step-card/use-step-config';
import { useStepConfig } from '../step-card/use-step-config';

export interface TraceViewerActionBlockClassNames {
  /** Root wrapper */
  root?: string;
  /** Left accent bar */
  accent?: string;
  /** Status icon area */
  indicator?: string;
  /** Action verb */
  action?: string;
  /** Target value */
  target?: string;
  /** Right meta area (duration + screenshot) */
  meta?: string;
  /** Screenshot thumbnail */
  screenshot?: string;
}

export interface TraceViewerActionBlockProps {
  /** The action verb (e.g. "Navigate to", "Click", "Type", "Wait for") */
  action: string;
  /** The target or argument (e.g. URL, selector, text value) */
  target?: string;
  /** Optional icon before the action */
  icon?: ReactNode;
  /** Step status */
  status?: StepCardStatus;
  /** Verdict type (overrides status icon via VerdictResultIndicator) */
  verdictType?: VerdictType;
  /** Color variant (auto-resolved from status + verdictType if not provided) */
  variant?: StepCardVariant;
  /** Video is currently at this step */
  active?: boolean;
  /** User has selected this step for inspection */
  selected?: boolean;
  /** Duration text (e.g. "1.2s") */
  duration?: string;
  /** Screenshot thumbnail URL */
  screenshotUrl?: string;
  /** Callback when screenshot is clicked */
  onScreenshotClick?: () => void;
  /** Callback when card is clicked */
  onClick?: () => void;
  /** Content rendered below the main row (e.g. output logs) */
  bottomContent?: ReactNode;
  /** Style overrides */
  classNames?: TraceViewerActionBlockClassNames;
}

export const TraceViewerActionBlock = ({
  action,
  target,
  icon,
  status,
  verdictType,
  active = false,
  selected = false,
  duration,
  screenshotUrl,
  onScreenshotClick,
  onClick,
  bottomContent,
  classNames,
}: TraceViewerActionBlockProps) => {
  const stepConfig: StepConfig = useStepConfig({ status, verdictType });
  const hasAccent = active || selected;

  const handleScreenshotClick = (e: React.MouseEvent) => {
    e.stopPropagation();
    onScreenshotClick?.();
  };

  return (
    <div
      className={cn(
        'flex overflow-hidden rounded-md border transition-colors',
        stepConfig.defaultBg,
        selected && stepConfig.selectedBg,
        onClick && 'cursor-pointer hover:bg-muted/50',
        classNames?.root,
      )}
      onClick={onClick}
    >
      {/* Left accent bar */}
      <div
        className={cn(
          'w-1 shrink-0',
          hasAccent ? stepConfig.accentColor : 'bg-transparent',
          classNames?.accent,
        )}
      />

      {/* Right side: top row + bottom content */}
      <div className="flex min-w-0 flex-1 flex-col">
        {/* Top row: status icon + action content + meta */}
        <div className="flex items-center">
          {/* Status icon */}
          {stepConfig.icon && (
            <div
              className={cn(
                'flex shrink-0 items-center pl-2.5 pr-2',
                classNames?.indicator,
              )}
            >
              {stepConfig.icon}
            </div>
          )}

          {/* Action content */}
          <div className="flex min-w-0 flex-1 items-center gap-2.5 py-2">
            {icon && (
              <span className="shrink-0 text-muted-foreground">{icon}</span>
            )}

            <span
              className={cn(
                'shrink-0 text-sm text-muted-foreground',
                classNames?.action,
              )}
            >
              {action}
            </span>

            {target && (
              <code
                className={cn(
                  'truncate rounded bg-muted px-1.5 py-0.5 font-mono text-xs font-medium text-foreground',
                  classNames?.target,
                )}
              >
                {target}
              </code>
            )}
          </div>

          {/* Meta: duration + screenshot */}
          <div
            className={cn(
              'flex shrink-0 items-center gap-3 px-3',
              classNames?.meta,
            )}
          >
            {screenshotUrl && (
              <button
                type="button"
                onClick={onScreenshotClick ? handleScreenshotClick : undefined}
                className={cn(
                  'group/screenshot relative shrink-0 overflow-hidden rounded border',
                  onScreenshotClick && 'cursor-pointer hover:opacity-80',
                  classNames?.screenshot,
                )}
              >
                <img
                  src={screenshotUrl}
                  alt="Step screenshot"
                  className="h-14 w-24 object-cover"
                />
              </button>
            )}
            {duration && (
              <span className="text-xs tabular-nums text-muted-foreground">
                {duration}
              </span>
            )}
          </div>
        </div>

        {/* Bottom content (e.g. output logs) */}
        {bottomContent && <div className="pb-1 pl-2.5">{bottomContent}</div>}
      </div>
    </div>
  );
};
