import {
  ChevronDownIcon,
  MaximizeIcon,
  MinimizeIcon,
  PauseIcon,
  PlayIcon,
  SkipBackIcon,
} from 'lucide-react';
import type { ReactNode } from 'react';

import { Button } from '../../../../components/button/button';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuTrigger,
} from '../../../../components/dropdown-menu/dropdown-menu';
import { formatTime } from '../_utils/format-time';
import {
  REWIND_INTERVAL_MS,
  type VideoController,
} from '../use-video-controller';

interface VideoPlayerControlsProps {
  controller: VideoController;
  timeline: ReactNode;
  isFullscreen: boolean;
  hasSrc: boolean;
  playbackRates: number[];
  onToggleFullscreen: () => void;
}

export const VideoPlayerControls = ({
  controller,
  timeline,
  isFullscreen,
  hasSrc,
  playbackRates,
  onToggleFullscreen,
}: VideoPlayerControlsProps) => {
  const { currentTimeMs, durationMs, isPlaying, playbackRate } =
    controller.state;
  const { togglePlay, seek, setPlaybackRate } = controller.actions;

  const handleRewind = () => seek(currentTimeMs - REWIND_INTERVAL_MS);

  const handleRateChange = (value: string) => setPlaybackRate(Number(value));

  return (
    <div className="bg-surface px-3 py-2">
      <div className="flex items-center gap-2">
        <Button
          variant="ghost"
          size="icon"
          tooltip={isPlaying ? 'Pause' : 'Play'}
          onClick={togglePlay}
          disabled={!hasSrc}
        >
          {isPlaying ? (
            <PauseIcon className="size-4" />
          ) : (
            <PlayIcon className="size-4" />
          )}
        </Button>

        <Button
          variant="ghost"
          size="icon"
          tooltip={`Rewind ${REWIND_INTERVAL_MS / 1000}s`}
          onClick={handleRewind}
          disabled={!hasSrc}
        >
          <SkipBackIcon className="size-4" />
        </Button>

        <span className="text-sm tabular-nums text-muted-foreground">
          {formatTime(currentTimeMs)} / {formatTime(durationMs)}
        </span>

        <div className="flex-1">{timeline}</div>

        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <Button
              variant="ghost"
              size="sm"
              tooltip="Playback speed"
              disabled={!hasSrc}
              className="gap-1 tabular-nums"
            >
              {playbackRate}x
              <ChevronDownIcon className="size-3.5" />
            </Button>
          </DropdownMenuTrigger>
          <DropdownMenuContent align="end" className="min-w-24">
            <DropdownMenuRadioGroup
              value={String(playbackRate)}
              onValueChange={handleRateChange}
            >
              {playbackRates.map((rate) => (
                <DropdownMenuRadioItem
                  key={rate}
                  value={String(rate)}
                  className="tabular-nums"
                >
                  {rate}x
                </DropdownMenuRadioItem>
              ))}
            </DropdownMenuRadioGroup>
          </DropdownMenuContent>
        </DropdownMenu>

        <Button
          variant="ghost"
          size="icon"
          tooltip={isFullscreen ? 'Exit fullscreen' : 'Fullscreen'}
          onClick={onToggleFullscreen}
        >
          {isFullscreen ? (
            <MinimizeIcon className="size-4" />
          ) : (
            <MaximizeIcon className="size-4" />
          )}
        </Button>
      </div>
    </div>
  );
};
