import {
  Button,
  DropdownMenu,
  DropdownMenuCheckboxItem,
  DropdownMenuContent,
  DropdownMenuLabel,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
  Input,
} from '@heal/front-core/ui';
import { FilterIcon, MoreHorizontalIcon, SearchIcon } from 'lucide-react';

import { useViewProvider } from '../../../../context/view-provider/view-provider.hooks';
import { TestListGroupBy } from '../../../../context/view-provider/view-provider.types';
import { AttemptStatus } from '../../../../types/attempt';

const STATUS_OPTIONS: { value: AttemptStatus; label: string }[] = [
  { value: 'passed', label: 'Passed' },
  { value: 'failed', label: 'Failed' },
  { value: 'timedOut', label: 'Timed out' },
  { value: 'skipped', label: 'Skipped' },
  { value: 'interrupted', label: 'Interrupted' },
];

const GROUP_BY_OPTIONS: { value: TestListGroupBy; label: string }[] = [
  { value: 'none', label: 'None' },
  { value: 'project', label: 'Project' },
  { value: 'team', label: 'Team' },
  { value: 'team-and-feature', label: 'Team & feature' },
];

export const TestListToolbar = () => {
  const { testListFilters, features } = useViewProvider();
  const {
    searchQuery,
    setSearchQuery,
    statusFilter,
    setStatusFilter,
    groupBy,
    setGroupBy,
  } = testListFilters;

  const handleToggleStatus = (status: AttemptStatus) => {
    if (statusFilter.includes(status)) {
      setStatusFilter(statusFilter.filter((s) => s !== status));
    } else {
      setStatusFilter([...statusFilter, status]);
    }
  };

  const hasActiveFilters = statusFilter.length > 0;

  return (
    <div className="flex shrink-0 flex-col gap-2 border-b px-3 py-2">
      <div className="flex items-center gap-1.5">
        <div className="relative flex-1">
          <SearchIcon className="absolute top-1/2 left-2 size-3.5 -translate-y-1/2 text-muted-foreground" />
          <Input
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            placeholder="Search tests..."
            className="h-7 pl-7 text-xs"
          />
        </div>
        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <Button
              variant="ghost"
              size="iconSm"
              className={hasActiveFilters ? 'text-info-solid' : ''}
            >
              <FilterIcon className="size-3.5" />
            </Button>
          </DropdownMenuTrigger>
          <DropdownMenuContent align="end">
            <DropdownMenuLabel>Filter by status</DropdownMenuLabel>
            <DropdownMenuSeparator />
            {STATUS_OPTIONS.map((option) => (
              <DropdownMenuCheckboxItem
                key={option.value}
                checked={statusFilter.includes(option.value)}
                onCheckedChange={() => handleToggleStatus(option.value)}
              >
                {option.label}
              </DropdownMenuCheckboxItem>
            ))}
          </DropdownMenuContent>
        </DropdownMenu>
        {features.showGroupBy ? (
          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <Button variant="ghost" size="iconSm">
                <MoreHorizontalIcon className="size-3.5" />
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent align="end">
              <DropdownMenuLabel>Group by</DropdownMenuLabel>
              <DropdownMenuSeparator />
              <DropdownMenuRadioGroup
                value={groupBy}
                onValueChange={(v) => setGroupBy(v as TestListGroupBy)}
              >
                {GROUP_BY_OPTIONS.map((option) => (
                  <DropdownMenuRadioItem
                    key={option.value}
                    value={option.value}
                  >
                    {option.label}
                  </DropdownMenuRadioItem>
                ))}
              </DropdownMenuRadioGroup>
            </DropdownMenuContent>
          </DropdownMenu>
        ) : null}
      </div>
    </div>
  );
};
