import { useContext } from 'react';

import { AuthSlotProviderContext } from './auth-slot-provider.context';

/**
 * Returns the host-supplied auth slot, or `null` when no host wired one in.
 * Unlike most providers in this package, this hook does NOT throw when the
 * provider is absent — the auth slot is opt-in.
 */
export const useAuthSlot = () => useContext(AuthSlotProviderContext);
