import { PropsWithChildren, ReactNode } from 'react';

import {
  TooltipProvider as TooltipProviderPrimitive,
  Tooltip as TooltipPrimitive,
  TooltipTrigger as TooltipTriggerPrimitive,
  TooltipContent as TooltipContentPrimitive,
} from '../tooltip/tooltip';

export interface CustomTooltipProps extends PropsWithChildren {
  content: ReactNode;
  enabled?: boolean;
  delayDuration?: number;
}

export const CustomTooltip = ({
  content,
  enabled = true,
  delayDuration = 0,
  children,
}: CustomTooltipProps) => {
  if (!enabled) {
    return children;
  }

  return (
    <TooltipProviderPrimitive>
      <TooltipPrimitive delayDuration={delayDuration}>
        <TooltipTriggerPrimitive asChild>{children}</TooltipTriggerPrimitive>
        <TooltipContentPrimitive>{content}</TooltipContentPrimitive>
      </TooltipPrimitive>
    </TooltipProviderPrimitive>
  );
};
