import {
  TraceViewerContainer,
  VerdictResultIndicator,
} from '@heal/front-core/ui';
import { useState, type KeyboardEvent, type MouseEvent } from 'react';

import { useCapabilities } from '../../../context/capabilities-provider/capabilities-provider.hooks';
import {
  useDataProvider,
  useVerdictStatement,
} from '../../../context/data-provider/data-provider.hooks';
import { useStatementProvider } from '../../../context/statement-provider/statement-provider.hooks';
import { useTriageVerdictForm } from '../../../context/triage-verdict-form-provider/triage-verdict-form-provider.hooks';
import { useViewProvider } from '../../../context/view-provider/view-provider.hooks';
import type { FinalVerdict, TriagedVerdict } from '../../../types/test';

import { ActionView } from './_components/action-view';
import { CodeView } from './_components/code-view';

export const TEST_CONTENT_VIEW_ID = 'test-content';

const TEST_CONTENT_TAB_STORAGE_KEY = 'heal:trace-viewer:test-content-tab';
const VALID_TEST_CONTENT_TABS = new Set(['steps', 'actions']);

const readStoredTab = (defaultTab: 'steps' | 'actions'): string => {
  if (typeof window === 'undefined') {
    return defaultTab;
  }
  const raw = window.localStorage.getItem(TEST_CONTENT_TAB_STORAGE_KEY);
  if (raw && VALID_TEST_CONTENT_TABS.has(raw)) {
    return raw;
  }

  return defaultTab;
};

export const TestContentView = () => {
  const { currentTest } = useDataProvider();
  const { features } = useViewProvider();
  const configuredDefaultTab = features.defaultTestContentTab;
  const [activeTab, setActiveTab] = useState<string>(() =>
    readStoredTab(configuredDefaultTab),
  );

  const handleActiveTabChange = (id: string) => {
    setActiveTab(id);
    window.localStorage.setItem(TEST_CONTENT_TAB_STORAGE_KEY, id);
  };

  const verdict = currentTest?.finalVerdict ?? currentTest?.triagedVerdict;

  return (
    <div className="flex h-full w-full flex-col overflow-hidden">
      {verdict && <VerdictBanner verdict={verdict} />}
      <div className="min-h-0 flex-1">
        <TraceViewerContainer
          scrollable
          activeView={activeTab}
          onActiveViewChange={handleActiveTabChange}
          views={[
            {
              id: 'steps',
              label: 'Steps',
              content: <CodeView />,
            },
            {
              id: 'actions',
              label: 'Actions',
              content: <ActionView />,
            },
          ]}
        />
      </div>
    </div>
  );
};

const VERDICT_BANNER_CLASS =
  'flex shrink-0 items-center gap-1.5 border-b border-border bg-muted/40 px-3 py-1.5 text-xs text-foreground';

const VerdictBanner = ({
  verdict,
}: {
  verdict: TriagedVerdict | FinalVerdict;
}) => {
  const { canWriteTriagedVerdict } = useCapabilities();
  const { open } = useTriageVerdictForm();
  const { selectActiveStatement } = useStatementProvider();
  const verdictHit = useVerdictStatement();

  const handleNavigateToStep = (event: MouseEvent<HTMLButtonElement>) => {
    event.stopPropagation();
    if (verdictHit) {
      selectActiveStatement(verdictHit.statement.id);
    }
  };

  const content = (
    <div className="flex items-center gap-1.5 text-xs font-semibold tracking-wide uppercase text-foreground">
      <VerdictResultIndicator
        verdictType={verdict.payload.type}
        variant="compact"
        size="sm"
        showTooltip={false}
      />
      <button
        type="button"
        onClick={handleNavigateToStep}
        className="cursor-pointer font-normal text-muted-foreground normal-case hover:text-foreground hover:underline h-0 flex items-center"
      >
        <span>at step {verdict.failingStatementIndex + 1}</span>
      </button>
    </div>
  );

  if (!canWriteTriagedVerdict) {
    return <div className={VERDICT_BANNER_CLASS}>{content}</div>;
  }

  const handleOpenOperator = () => {
    open();
  };

  return (
    <div
      role="button"
      tabIndex={0}
      onClick={handleOpenOperator}
      onKeyDown={getOperatorKeyDownHandler(handleOpenOperator)}
      className={`${VERDICT_BANNER_CLASS} w-full cursor-pointer text-left transition-colors hover:bg-muted/60`}
    >
      {content}
    </div>
  );
};

const getOperatorKeyDownHandler =
  (onActivate: () => void) => (event: KeyboardEvent<HTMLDivElement>) => {
    if (event.key !== 'Enter' && event.key !== ' ') {
      return;
    }
    event.preventDefault();
    onActivate();
  };
