import { useContext, useMemo } from 'react';

import type { FinalVerdict, Statement, TriagedVerdict } from '../../types/test';

import { DataProviderContext } from './data-provider.context';

export const useDataProvider = () => {
  const context = useContext(DataProviderContext);
  if (!context) {
    throw new Error('useDataProvider must be used within a DataProvider');
  }

  return context;
};

/**
 * Resolves the statement the active verdict points to via its 0-based
 * `failingStatementIndex`. Final verdict wins over triaged when present.
 * Returns `null` when no verdict, no current test, or the index is out of
 * range. Centralized so every view that highlights the verdict step (code
 * list, video timeline, etc.) shares the same interpretation.
 */
export const useVerdictStatement = (): {
  statement: Statement;
  verdict: FinalVerdict | TriagedVerdict;
} | null => {
  const { currentTest } = useDataProvider();

  return useMemo(() => {
    if (!currentTest) return null;
    const verdict = currentTest.finalVerdict ?? currentTest.triagedVerdict;
    if (!verdict) return null;
    const statement =
      currentTest.statements[verdict.failingStatementIndex] ?? null;

    return statement ? { statement, verdict } : null;
  }, [currentTest]);
};
