import { useMemo } from 'react';

import { EventProviderContext } from './event-provider.context';
import { EventProviderProps } from './event-provider.types';

export const EventProvider = ({
  children,
  onTestCaseClick,
  onVerdictClassify,
  onVerdictCreate,
  onAutopilotTrigger,
  isAutopilotPending,
}: EventProviderProps) => {
  const value = useMemo(
    () => ({
      onTestCaseClick,
      onVerdictClassify,
      onVerdictCreate,
      onAutopilotTrigger,
      isAutopilotPending,
    }),
    [
      onTestCaseClick,
      onVerdictClassify,
      onVerdictCreate,
      onAutopilotTrigger,
      isAutopilotPending,
    ],
  );

  return (
    <EventProviderContext.Provider value={value}>
      {children}
    </EventProviderContext.Provider>
  );
};
