import { XIcon } from 'lucide-react';
import { type ReactNode, useState } from 'react';

import { cn } from '../../../../lib/utils';

export interface PageDefinition<TProps> {
  /** Unique identifier for the page */
  id: string;
  /** Label displayed in the tab */
  label: ReactNode;
  /** Props passed to renderPage for this page */
  props: TProps;
  /** Optional icon rendered before the label */
  icon?: ReactNode;
  /** Whether the tab is closable */
  closable?: boolean;
}

export interface TraceViewerPagesContainerClassNames {
  /** Root wrapper */
  root?: string;
  /** Tab bar */
  tabBar?: string;
  /** Individual tab */
  tab?: string;
  /** Active tab */
  tabActive?: string;
  /** Content area */
  content?: string;
}

export interface TraceViewerPagesContainerProps<TProps> {
  /** Array of pages. Each page renders the same component with different props. */
  pages: PageDefinition<TProps>[];
  /** Render function called with the page props */
  renderPage: (props: TProps, page: PageDefinition<TProps>) => ReactNode;
  /** Controlled active page id */
  activePage?: string;
  /** Callback when the active page changes */
  onActivePageChange?: (id: string) => void;
  /** Uncontrolled default active page id. Defaults to first page. */
  defaultActivePage?: string;
  /** Callback when a page close button is clicked */
  onPageClose?: (id: string) => void;
  /** When true, content area scrolls internally. Default: false */
  scrollable?: boolean;
  /** Override classNames for internal elements */
  classNames?: TraceViewerPagesContainerClassNames;
}

export const TraceViewerPagesContainer = <TProps,>({
  pages,
  renderPage,
  activePage: controlledActive,
  onActivePageChange,
  defaultActivePage,
  onPageClose,
  scrollable = false,
  classNames,
}: TraceViewerPagesContainerProps<TProps>) => {
  const [uncontrolledActive, setUncontrolledActive] = useState(
    defaultActivePage ?? pages[0]?.id,
  );

  const isControlled = controlledActive !== undefined;
  const activeId = isControlled ? controlledActive : uncontrolledActive;

  const handleTabClick = (id: string) => {
    if (!isControlled) {
      setUncontrolledActive(id);
    }
    onActivePageChange?.(id);
  };

  const handleClose = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    onPageClose?.(id);
  };

  if (pages.length === 0) {
    return null;
  }

  const activePage = pages.find((p) => p.id === activeId) ?? pages[0];
  const overflowClass = scrollable ? 'overflow-auto' : 'overflow-hidden';

  return (
    <div
      className={cn(
        'flex h-full w-full flex-col overflow-hidden border bg-surface',
        classNames?.root,
      )}
    >
      {/* File-style tab bar */}
      <div
        className={cn(
          'flex shrink-0 items-end overflow-x-auto border-b bg-muted/50 [scrollbar-width:none] [&::-webkit-scrollbar]:hidden',
          classNames?.tabBar,
        )}
      >
        {pages.map((page) => {
          const isActive = page.id === activeId;

          return (
            <button
              key={page.id}
              type="button"
              onClick={() => handleTabClick(page.id)}
              className={cn(
                'group relative flex shrink-0 items-center gap-1.5 border-r px-3 py-1.5 text-xs transition-colors',
                isActive
                  ? 'bg-surface text-foreground -mb-px border-b border-b-surface'
                  : 'text-muted-foreground hover:bg-surface/50 hover:text-foreground',
                classNames?.tab,
                isActive && classNames?.tabActive,
              )}
            >
              {page.icon && <span className="shrink-0">{page.icon}</span>}
              <span className="truncate">{page.label}</span>
              {page.closable && onPageClose && (
                <span
                  role="button"
                  tabIndex={-1}
                  onClick={(e) => handleClose(e, page.id)}
                  className={cn(
                    'ml-1 shrink-0 rounded p-0.5 transition-colors',
                    'opacity-0 group-hover:opacity-100',
                    isActive && 'opacity-100',
                    'hover:bg-muted-foreground/20',
                  )}
                >
                  <XIcon className="size-3" />
                </span>
              )}
            </button>
          );
        })}

        {/* Fill remaining space */}
        <div className="flex-1" />
      </div>

      {/* Content */}
      <div className={cn('flex-1', overflowClass, classNames?.content)}>
        {renderPage(activePage.props, activePage)}
      </div>
    </div>
  );
};
