import { Navigate, Route, Routes, useParams } from 'react-router';

import { AuthSlotProvider } from './context/auth-slot-provider/auth-slot-provider';
import { AuthSlotProviderProps } from './context/auth-slot-provider/auth-slot-provider.types';
import { CapabilitiesProvider } from './context/capabilities-provider/capabilities-provider';
import { CapabilitiesProviderProps } from './context/capabilities-provider/capabilities-provider.types';
import { DataProvider } from './context/data-provider/data-provider';
import { DataProviderProps } from './context/data-provider/data-provider.types';
import { EventProvider } from './context/event-provider/event-provider';
import { EventProviderProps } from './context/event-provider/event-provider.types';
import { ExecutionProvider } from './context/execution-provider/execution-provider';
import { ExecutionProviderProps } from './context/execution-provider/execution-provider.types';
import { NavigationProvider } from './context/navigation-provider/navigation-provider';
import { NavigationProviderProps } from './context/navigation-provider/navigation-provider.types';
import { StatementProvider } from './context/statement-provider/statement-provider';
import { TriageVerdictFormProvider } from './context/triage-verdict-form-provider/triage-verdict-form-provider';
import { VideoProvider } from './context/video-provider/video-provider';
import { ViewProvider } from './context/view-provider/view-provider';
import { ViewProviderProps } from './context/view-provider/view-provider.types';
import { DefaultMode } from './features/mode/default.mode';
import { TRIAGE_MODE_ID, TriageMode } from './features/mode/triage.mode';
import { VERDICT_MODE_ID, VerdictMode } from './features/mode/verdict.mode';

export interface TracerProps {
  testList: DataProviderProps['testList'];
  currentTest: DataProviderProps['currentTest'];
  basePath: NavigationProviderProps['basePath'];
  onParamsChange?: NavigationProviderProps['onParamsChange'];
  onTestCaseClick?: EventProviderProps['onTestCaseClick'];
  onVerdictClassify?: EventProviderProps['onVerdictClassify'];
  onVerdictCreate?: EventProviderProps['onVerdictCreate'];
  onAutopilotTrigger?: EventProviderProps['onAutopilotTrigger'];
  isAutopilotPending?: EventProviderProps['isAutopilotPending'];
  capabilities?: CapabilitiesProviderProps['capabilities'];
  features?: CapabilitiesProviderProps['features'] &
    ViewProviderProps['features'];
  executions?: ExecutionProviderProps['executions'];
  currentExecutionId?: ExecutionProviderProps['currentExecutionId'];
  onExecutionChange?: ExecutionProviderProps['onExecutionChange'];
  mode?: ViewProviderProps['mode'];
  loading?: DataProviderProps['loading'];
  /**
   * Optional render slot for the auth chip rendered in the top-right of the
   * header. Opt-in: when omitted, the slot renders nothing and consumers see
   * no behavioural change. Used by the open-source trace viewer to surface
   * the freemium funnel (install CLI / sign in / profile chip).
   */
  authSlot?: AuthSlotProviderProps['authSlot'];
}

function SafeRedirect(props: TracerProps) {
  const { executionId, testId } = useParams<{
    executionId: string;
    testId: string;
  }>();

  return (
    <Navigate
      to={`${props.basePath}/executions/${executionId}/tests/${testId}/attempts/1`}
    />
  );
}

export const Tracer = (props: TracerProps) => {
  return (
    <Routes>
      <Route index element={<Content {...props} />} />
      <Route path="executions/:executionId" element={<Content {...props} />} />
      <Route
        path="executions/:executionId/tests/:testId/"
        element={<SafeRedirect {...props} />}
      />
      <Route
        path="executions/:executionId/tests/:testId/attempts/:attemptNumber"
        element={<Content {...props} />}
      />
    </Routes>
  );
};

const Content = (props: TracerProps) => {
  const navigationProviderProps = {
    basePath: props.basePath,
    onParamsChange: props.onParamsChange,
  };

  const dataProviderProps = {
    testList: props.testList,
    currentTest: props.currentTest,
    loading: props.loading,
  };

  const eventProviderProps = {
    onTestCaseClick: props.onTestCaseClick,
    onVerdictClassify: props.onVerdictClassify,
    onVerdictCreate: props.onVerdictCreate,
    onAutopilotTrigger: props.onAutopilotTrigger,
    isAutopilotPending: props.isAutopilotPending,
  };

  const capabilitiesProviderProps = {
    capabilities: props.capabilities,
    features: props.features,
  };

  return (
    <NavigationProvider {...navigationProviderProps}>
      <CapabilitiesProvider {...capabilitiesProviderProps}>
        <AuthSlotProvider authSlot={props.authSlot}>
          <EventProvider {...eventProviderProps}>
            <ExecutionProvider
              executions={props.executions}
              currentExecutionId={props.currentExecutionId}
              onExecutionChange={props.onExecutionChange}
            >
              <ViewProvider features={props.features} mode={props.mode}>
                <DataProvider {...dataProviderProps}>
                  <TriageVerdictFormProvider>
                    <VideoProvider>
                      <StatementProvider>
                        <Mode mode={props.mode} />
                      </StatementProvider>
                    </VideoProvider>
                  </TriageVerdictFormProvider>
                </DataProvider>
              </ViewProvider>
            </ExecutionProvider>
          </EventProvider>
        </AuthSlotProvider>
      </CapabilitiesProvider>
    </NavigationProvider>
  );
};

const Mode = ({ mode }: { mode: TracerProps['mode'] }) => {
  switch (mode) {
    case VERDICT_MODE_ID:
      return <VerdictMode />;
    case TRIAGE_MODE_ID:
      return <TriageMode />;
    default:
      return <DefaultMode />;
  }
};
