import { useContext } from 'react';

import { CapabilitiesProviderContext } from './capabilities-provider.context';

const useCapabilitiesProvider = () => {
  const context = useContext(CapabilitiesProviderContext);
  if (!context) {
    throw new Error(
      'useCapabilities/useFeatures must be used within a CapabilitiesProvider',
    );
  }

  return context;
};

export const useCapabilities = () => useCapabilitiesProvider().capabilities;

export const useFeatures = () => useCapabilitiesProvider().features;
