import { cn } from '@heal/front-core/lib/utils';
import { Button, Skeleton } from '@heal/front-core/ui';
import { ArrowSquareOutIcon } from '@phosphor-icons/react';

import { useAuthSlot } from '../../context/auth-slot-provider/auth-slot-provider.hooks';
import type { AuthProfile } from '../../types/auth';

const HEAL_INSTALL_URL = 'https://docs.heal.dev/docs/cli/getting-started';

const initialsFor = (p: AuthProfile): string => {
  const first = p.firstName?.trim()?.[0];
  const last = p.lastName?.trim()?.[0];
  if (first && last) return (first + last).toUpperCase();
  if (first) return first.toUpperCase();
  if (p.username) return p.username.slice(0, 2).toUpperCase();

  return p.email.slice(0, 2).toUpperCase();
};

const displayNameFor = (p: AuthProfile): string => {
  const full = [p.firstName, p.lastName].filter(Boolean).join(' ').trim();
  if (full) return full;
  if (p.username) return p.username;

  return p.email;
};

/**
 * Renders the auth chip in the trace viewer's header. The slot is opt-in:
 * if no host wired an `authSlot` prop into `<Tracer>`, this renders nothing.
 */
export const AuthSlot = () => {
  const slot = useAuthSlot();
  if (!slot) return null;
  const { state, onSignIn } = slot;

  switch (state.status) {
    case 'loading':
      // Width matches the rough footprint of the logged-in chip so the
      // header doesn't reflow when state resolves.
      return <Skeleton className="h-8 w-[140px] rounded-md" />;

    case 'not_installed':
      return (
        <a
          href={HEAL_INSTALL_URL}
          target="_blank"
          rel="noreferrer noopener"
          className={cn(
            'inline-flex h-8 max-w-[280px] items-center gap-1.5 rounded-md',
            'px-2.5 text-xs text-muted-foreground hover:text-foreground',
            'border border-transparent hover:border-muted',
            'transition-colors',
          )}
          title="Install Heal CLI to unlock test analysis and auto-fix"
        >
          <span className="truncate">
            Install Heal CLI to unlock test analysis and auto-fix
          </span>
          <ArrowSquareOutIcon className="size-3.5 shrink-0" aria-hidden />
        </a>
      );

    case 'logged_out':
      return (
        <Button variant="primary" size="sm" onClick={onSignIn}>
          Sign in
        </Button>
      );

    case 'logged_in': {
      const { profile } = state;
      const name = displayNameFor(profile);
      const org = profile.organization?.name;

      return (
        <div
          className={cn(
            'inline-flex h-8 max-w-[260px] items-center gap-2',
            'rounded-md border border-muted bg-surface-elevated px-1.5',
          )}
          title={org ? `${name} — ${org}` : name}
        >
          <span
            className={cn(
              'flex size-6 shrink-0 items-center justify-center',
              'rounded-full bg-brand-solid text-[10px] font-semibold uppercase',
              'text-brand-solid-contrast',
            )}
            aria-hidden
          >
            {initialsFor(profile)}
          </span>
          <div className="flex min-w-0 flex-col leading-tight">
            <span className="truncate text-xs text-foreground">{name}</span>
            {org && (
              <span className="truncate text-[10px] text-muted-foreground">
                {org}
              </span>
            )}
          </div>
        </div>
      );
    }
  }
};
