import {
  ArrowSquareOutIcon,
  CheckCircleIcon,
  CircleNotchIcon,
  GitPullRequestIcon,
  WarningCircleIcon,
  type Icon,
} from '@phosphor-icons/react';
import type { ReactNode } from 'react';

import { cn } from '../../../../lib/utils';
import { Button } from '../../../components/button/button';

// ─── Types ──────────────────────────────────────────────────────

export type TraceViewerAutopilotFixStatus =
  | 'pending'
  | 'pushed'
  | 'completed'
  | 'failed';

export interface TraceViewerAutopilotFix {
  status: TraceViewerAutopilotFixStatus;
  branchName?: string | null;
  prUrl?: string | null;
  prNumber?: number | null;
  error?: string | null;
}

export interface TraceViewerAutopilotBannerProps {
  /** Current autopilot fix state. `null` renders the idle (trigger) banner. */
  autopilotFix: TraceViewerAutopilotFix | null;
  /** Whether a trigger mutation is currently in flight on the host side. */
  isPending?: boolean;
  /** Fired when the user clicks the idle / retry CTA. */
  onTrigger: () => void;
  /** Style overrides for the outer container. */
  className?: string;
}

// ─── Variant styles ─────────────────────────────────────────────

interface BannerVariantStyles {
  container: string;
  iconWrapper: string;
}

const VARIANTS: Record<
  'progress' | 'open' | 'merged' | 'failed',
  BannerVariantStyles
> = {
  progress: {
    container: 'border-info-solid/30 bg-info-subtle',
    iconWrapper: 'bg-info-solid/20 text-info-solid',
  },
  open: {
    container: 'border-success-solid/30 bg-success-subtle',
    iconWrapper: 'bg-success-solid/20 text-success-solid',
  },
  merged: {
    container: 'border-brand-solid/30 bg-brand-subtle',
    iconWrapper: 'bg-brand-solid/20 text-brand-solid',
  },
  failed: {
    container: 'border-danger-solid/30 bg-danger-subtle',
    iconWrapper: 'bg-danger-solid/20 text-danger-solid',
  },
};

// ─── Component ──────────────────────────────────────────────────

export const TraceViewerAutopilotBanner = ({
  autopilotFix,
  isPending = false,
  onTrigger,
  className,
}: TraceViewerAutopilotBannerProps) => {
  const status = autopilotFix?.status;

  if (!status) {
    return null;
  }

  if (isPending || status === 'pending') {
    return (
      <BannerShell
        variant="progress"
        Icon={CircleNotchIcon}
        iconClass="animate-spin"
        title="Autopilot is generating a fix…"
        description={
          autopilotFix?.branchName
            ? `Pushing to branch ${autopilotFix.branchName}.`
            : 'This usually takes under a minute.'
        }
        className={className}
      />
    );
  }

  if (status === 'pushed') {
    return (
      <BannerShell
        variant="open"
        Icon={GitPullRequestIcon}
        title={
          autopilotFix?.prNumber
            ? `PR #${autopilotFix.prNumber} is open for review`
            : 'Autopilot opened a pull request'
        }
        description={
          autopilotFix?.branchName
            ? `Branch ${autopilotFix.branchName} is awaiting review.`
            : 'The pull request is awaiting review.'
        }
        action={renderViewPrButton(autopilotFix)}
        className={className}
      />
    );
  }

  if (status === 'completed') {
    return (
      <BannerShell
        variant="merged"
        Icon={CheckCircleIcon}
        title={
          autopilotFix?.prNumber
            ? `PR #${autopilotFix.prNumber} merged`
            : 'Autopilot fix merged'
        }
        description={
          autopilotFix?.branchName
            ? `Branch ${autopilotFix.branchName} has been merged.`
            : 'The pull request has been merged.'
        }
        action={renderViewPrButton(autopilotFix)}
        className={className}
      />
    );
  }

  if (status === 'failed') {
    return (
      <BannerShell
        variant="failed"
        Icon={WarningCircleIcon}
        title="Autopilot couldn't open a PR"
        description={autopilotFix?.error ?? 'Autopilot failed.'}
        action={
          <Button
            type="button"
            variant="secondary"
            size="sm"
            onClick={onTrigger}
            className="h-7 gap-1.5 text-xs"
          >
            Retry
          </Button>
        }
        className={className}
      />
    );
  }

  return null;
};

// ─── Internals ──────────────────────────────────────────────────

const renderViewPrButton = (
  autopilotFix: TraceViewerAutopilotFix | null,
): ReactNode => {
  if (!autopilotFix?.prUrl) {
    return null;
  }

  return (
    <Button
      type="button"
      variant="secondary"
      size="sm"
      className="h-7 gap-1.5 text-xs"
      asChild
    >
      <a
        href={autopilotFix.prUrl}
        target="_blank"
        rel="noopener noreferrer"
        className="inline-flex items-center gap-1.5"
      >
        <ArrowSquareOutIcon size={12} aria-hidden />
        View PR
      </a>
    </Button>
  );
};

interface BannerShellProps {
  variant: keyof typeof VARIANTS;
  Icon: Icon;
  iconClass?: string;
  title: string;
  description?: string;
  action?: ReactNode;
  className?: string;
}

const BannerShell = ({
  variant,
  Icon,
  iconClass,
  title,
  description,
  action,
  className,
}: BannerShellProps) => {
  const styles = VARIANTS[variant];

  return (
    <div
      className={cn(
        'flex items-center gap-3 rounded-md border px-3 py-2',
        styles.container,
        className,
      )}
    >
      <span
        className={cn(
          'flex size-7 shrink-0 items-center justify-center rounded-full',
          styles.iconWrapper,
        )}
        aria-hidden
      >
        <Icon size={14} className={iconClass} weight="fill" />
      </span>
      <div className="flex min-w-0 flex-1 flex-col">
        <span className="text-xs font-semibold text-foreground">{title}</span>
        {description && (
          <span className="text-xs text-muted-foreground">{description}</span>
        )}
      </div>
      {action && <div className="shrink-0">{action}</div>}
    </div>
  );
};
