import { VerdictResultIndicator } from '@heal/front-core/ui';

import type { FinalVerdict, TriagedVerdict } from '../../../../types/test';

interface VerdictHeadlineProps {
  verdict: TriagedVerdict | FinalVerdict;
}

/**
 * Compact verdict label used as the section title inside both the result pane
 * and the final-verdict card. Renders as: `[icon] TYPE  at step N`.
 */
export const VerdictHeadline = ({ verdict }: VerdictHeadlineProps) => (
  <div className="flex items-center gap-1.5 text-xs font-semibold tracking-wide uppercase text-foreground">
    <VerdictResultIndicator
      verdictType={verdict.payload.type}
      variant="compact"
      size="md"
      showTooltip={false}
    />
    <div className="flex items-center">
      <span className="font-normal text-muted-foreground normal-case h-0 flex items-center">
        at step {verdict.failingStatementIndex + 1}
      </span>
    </div>
  </div>
);
