import { FileTextIcon } from '@phosphor-icons/react';

import { TraceViewerContainer } from '../../../../../core/ui/features/trace-viewer';
import { CodeViewer } from '../../../components/code-viewer/code-viewer';
import { useDataProvider } from '../../../context/data-provider/data-provider.hooks';
import { EmptyState } from '../_components/empty-state';

export const TEST_CASE_VIEW_ID = 'test-case';

export const TestCaseView = () => {
  return (
    <TraceViewerContainer
      scrollable
      defaultActiveView="test-case"
      views={[
        {
          id: 'test-case',
          label: 'Test case',
          content: <TestCaseViewContent />,
        },
      ]}
    />
  );
};

export const TestCaseViewContent = () => {
  const { currentTest } = useDataProvider();

  if (!currentTest?.testCase) {
    return (
      <EmptyState
        icon={<FileTextIcon className="h-10 w-10" weight="thin" />}
        message="No test case linked."
      />
    );
  }
  if (!currentTest.testCase.content) {
    return (
      <EmptyState
        icon={<FileTextIcon className="h-10 w-10" weight="thin" />}
        message="This test case has no content yet."
      />
    );
  }

  return (
    <div className="flex h-full min-h-0 w-full flex-col overflow-hidden bg-background">
      <div className="min-h-0 flex-1">
        <CodeViewer
          content={currentTest.testCase.content}
          language="typescript"
        />
      </div>
    </div>
  );
};
