import { useContext } from 'react';

import { StatementProviderContext } from './statement-provider.context';

export const useStatementProvider = () => {
  const context = useContext(StatementProviderContext);
  if (!context) {
    throw new Error(
      'useStatementProvider must be used within a StatementProvider',
    );
  }

  return context;
};
