import type { ReactNode } from 'react';
import { useEffect, useState } from 'react';
import { codeToTokens, type BundledLanguage, type ThemedToken } from 'shiki';

import {
  HoverCard,
  HoverCardContent,
  HoverCardTrigger,
} from '../../../../lib/shadcn/hover-card';
import { cn } from '../../../../lib/utils';
import type { TraceViewerErrorInfo } from '../stack-trace/trace-viewer-stack-trace';
import { TraceViewerStackTrace } from '../stack-trace/trace-viewer-stack-trace';
import type {
  StepCardStatus,
  StepCardVariant,
  StepConfig,
  VerdictType,
} from '../step-card/use-step-config';
import { useStepConfig } from '../step-card/use-step-config';

// ─── Types ──────────────────────────────────────────────────────

export interface TraceViewerCodeBlockClassNames {
  /** Root wrapper */
  root?: string;
  /** Individual line row */
  line?: string;
  /** Gutter area (icon + line number + duration) */
  gutter?: string;
  /** Code content area */
  code?: string;
}

export interface TraceViewerCodeBlockProps {
  /** Code string to display (supports multiline) */
  code: string;
  /** Language for syntax highlighting (default: typescript) */
  language?: BundledLanguage;
  /** Shiki theme. Defaults to github-light/dark based on the `dark` class on <html>. */
  theme?: string;
  /** Starting line number (allows continuous numbering across blocks) */
  lineNumber?: number;
  /** Nesting indent level (indents code only, gutter stays aligned) */
  indent?: number;
  /** Step status */
  status?: StepCardStatus;
  /** Verdict type (overrides status icon via VerdictResultIndicator) */
  verdictType?: VerdictType;
  /** Color variant (auto-resolved from status + verdictType if not provided) */
  variant?: StepCardVariant;
  /** Video is currently at this step */
  active?: boolean;
  /** User has selected this step for inspection */
  selected?: boolean;
  /** Duration text (e.g. "1.2s") */
  duration?: string;
  /** Callback when block is clicked */
  onClick?: () => void;
  /** Content rendered below the code lines (e.g. output logs) */
  bottomContent?: ReactNode;
  /** Error to display as a collapsible stack-trace panel below the code */
  error?: TraceViewerErrorInfo;
  /** Style overrides */
  classNames?: TraceViewerCodeBlockClassNames;
}

// ─── Line background highlight (applied via box-shadow inset to layer over bg-background) ──

const VARIANT_LINE_HIGHLIGHT: Partial<Record<StepCardVariant, string>> = {
  danger: 'bg-danger-subtle',
  brand: 'bg-brand-subtle',
};

const VARIANT_ACTIVE_LINE_HIGHLIGHT: Partial<Record<StepCardVariant, string>> =
  {
    danger: 'bg-danger-subtle',
    brand: 'bg-brand-subtle',
    neutral: 'bg-info-subtle',
    info: 'bg-info-subtle',
    warning: 'bg-warning-subtle',
    success: 'bg-success-subtle',
  };

// ─── Left bar decoration (editor-style gutter marker) ───────────

const ACCENT_BORDER: Record<StepCardVariant, string> = {
  danger: 'border-l-danger-solid',
  success: 'border-l-success-solid',
  warning: 'border-l-warning-solid',
  brand: 'border-l-brand-solid',
  info: 'border-l-info-solid',
  neutral: 'border-l-info-solid',
};

// ─── Dark-mode detection (watches the `dark` class on <html>) ───

const useIsDarkMode = (): boolean => {
  const [isDark, setIsDark] = useState(
    () =>
      typeof document !== 'undefined' &&
      document.documentElement.classList.contains('dark'),
  );

  useEffect(() => {
    if (typeof document === 'undefined') return;
    const root = document.documentElement;
    const update = () => setIsDark(root.classList.contains('dark'));
    update();
    const observer = new MutationObserver(update);
    observer.observe(root, { attributes: true, attributeFilter: ['class'] });

    return () => observer.disconnect();
  }, []);

  return isDark;
};

// ─── Component ──────────────────────────────────────────────────

export const TraceViewerCodeBlock = ({
  code,
  language = 'typescript',
  theme,
  lineNumber = 1,
  indent = 0,
  status,
  verdictType,
  active = false,
  selected = false,
  duration,
  onClick,
  bottomContent,
  error,
  classNames,
}: TraceViewerCodeBlockProps) => {
  const [tokenLines, setTokenLines] = useState<ThemedToken[][] | null>(null);
  const isDark = useIsDarkMode();
  const resolvedTheme =
    theme ?? (isDark ? 'github-dark-default' : 'github-light-default');
  const stepConfig: StepConfig = useStepConfig({ status, verdictType });

  const lines = code.split('\n');

  // --- Tokenize with shiki ---

  useEffect(() => {
    let cancelled = false;

    const tokenize = async () => {
      const result = await codeToTokens(code, {
        lang: language,
        theme: resolvedTheme,
      });
      if (!cancelled) {
        setTokenLines(result.tokens);
      }
    };

    tokenize();

    return () => {
      cancelled = true;
    };
  }, [code, language, resolvedTheme]);

  const displayLines =
    tokenLines ??
    lines.map((line) => [{ content: line, color: undefined }] as ThemedToken[]);

  const hasAccent = active || selected;
  const hasHighlight =
    selected && VARIANT_ACTIVE_LINE_HIGHLIGHT[stepConfig.variant];
  const lineHighlight = VARIANT_LINE_HIGHLIGHT[stepConfig.variant];

  const block = (
    <div
      className={cn(
        'group/code-block',
        onClick && 'cursor-pointer',
        error && 'cursor-help',
        classNames?.root,
        lineHighlight,
        hasHighlight,
      )}
      onClick={onClick}
    >
      {displayLines.map((tokens, index) => {
        const isFirstLine = index === 0;
        const isLastLine = index === displayLines.length - 1;

        return (
          <div
            key={`${lineNumber}-${index}`}
            className={cn('flex w-fit min-w-full', classNames?.line)}
          >
            {/* Gutter: sticky left, opaque bg, accent border */}
            <div
              className={cn(
                'sticky left-0 z-10 flex min-h-6 w-fit shrink-0 items-center self-stretch border-l-2 bg-background pr-[16px] pl-1',
                hasAccent
                  ? ACCENT_BORDER[stepConfig.variant]
                  : 'border-l-transparent',
                classNames?.gutter,
                isFirstLine ? 'pt-0.5' : '',
                isLastLine ? 'pb-0.5' : '',
                lineHighlight,
                hasHighlight,
              )}
            >
              {/* Status icon */}
              <span className="flex w-5 items-center justify-center">
                {isFirstLine && stepConfig.icon ? stepConfig.icon : null}
              </span>

              {/* Duration (first line only) */}
              <span className="w-12 pl-2 text-right font-mono text-[11px] tabular-nums text-muted-foreground/50">
                {isFirstLine && duration ? duration : ''}
              </span>
            </div>

            {/* Code (shiki tokens) */}
            <code
              className={cn(
                'whitespace-pre bg-background pr-4 font-mono text-[13px] leading-6',
                classNames?.code,
                lineHighlight,
                hasHighlight,
              )}
            >
              {/* Indent guides */}
              <span className="inline-flex pl-0">
                {Array.from({ length: indent + 1 }, (_, i) => (
                  <span
                    key={i}
                    className={cn(
                      'inline-block w-4 border-l border-muted-foreground/35 pt-1 pb-1',
                      indent === 0 || i === 0 ? 'opacity-0 w-1' : 'opacity-100',
                    )}
                  >
                    &nbsp;
                  </span>
                ))}
              </span>
              {tokens.map((token, tokenIndex) => (
                <span key={tokenIndex} style={{ color: token.color }}>
                  {token.content}
                </span>
              ))}
              {tokens.length === 0 && ' '}
            </code>
          </div>
        );
      })}

      {/* Bottom content (e.g. output logs) rendered once below the lines */}
      {bottomContent ? <div>{bottomContent}</div> : null}
    </div>
  );

  if (!error) {
    return block;
  }

  return (
    <HoverCard openDelay={500} closeDelay={300}>
      <HoverCardTrigger asChild>{block}</HoverCardTrigger>
      <HoverCardContent
        align="start"
        sideOffset={6}
        className="w-[600px] max-w-[90vw] overflow-hidden p-0"
      >
        <TraceViewerStackTrace error={error} />
      </HoverCardContent>
    </HoverCard>
  );
};
