// Mappers from the tracer's wire format (as exposed by
// `@heal-dev/heal-playwright-tracer`'s local HTTP server) to the
// shapes consumed by `@heal-dev/front-run-viewer`'s `<Tracer>`.
//
// Two non-obvious choices, both load-bearing:
//
// 1. `executionId` flows through end-to-end. The server scopes
//    everything by execution; the SPA stores the currently-selected
//    one and routes <Tracer>'s `(executionId, playwrightTestId,
//    attempt)` triple off of it.
//
// 2. We fold our flat `TestSummary[]` (one entry per attempt
//    directory on disk) into one `TestListItem` per
//    `(file, title, project)` triple, with attempts as children.
//    Otherwise the attempt-selector in the header would always read
//    "Attempt 1 / 1" even on retried tests.

import type { TestList, TestListItem } from '@heal-dev/front-run-viewer';
import type {
  Statement as TracerStatement,
  Test as TracerTest,
} from '@heal-dev/front-run-viewer';

import type { Statement, TestSummary, TraceModel } from '../api';

const groupKey = (s: TestSummary): string =>
  `${s.file}::${s.title}::${s.project}`;

export const toTestList = (
  executionId: string,
  summaries: TestSummary[],
): TestList => {
  const groups = new Map<string, TestSummary[]>();
  for (const s of summaries) {
    const k = groupKey(s);
    const arr = groups.get(k) ?? [];
    arr.push(s);
    groups.set(k, arr);
  }

  const items: TestListItem[] = [];
  for (const arr of groups.values()) {
    arr.sort((a, b) => a.attempt - b.attempt);
    const head = arr[0];
    items.push({
      executionId,
      title: head.title,
      file: head.file,
      project: head.project,
      repoName: 'local',
      testCase: null,
      attempts: arr.map((a) => ({
        playwrightTestId: a.playwrightTestId,
        attempt: a.attempt,
        status: a.status === 'unknown' ? null : a.status,
        startedAt: new Date(a.startedAt).toISOString(),
        durationMs: a.duration,
        triagedVerdict: null,
        finalVerdict: null,
      })),
    });
  }

  // Stable ordering: by file then title
  items.sort((a, b) => {
    const byFile = (a.file ?? '').localeCompare(b.file ?? '');
    if (byFile !== 0) {
      return byFile;
    }

    return (a.title ?? '').localeCompare(b.title ?? '');
  });

  return items;
};

const mapStatement = (stmt: Statement): TracerStatement => ({
  id: stmt.seq,
  code: stmt.source,
  status: stmt.status === 'ok' ? 'passed' : 'failed',
  timestampMs: stmt.t,
  durationMs: stmt.duration,
  comment: stmt.leadingComment ?? null,
  children: stmt.children.map(mapStatement),
  screenshot: stmt.screenshot ?? null,
  error: stmt.error ?? null,
});

const findPlaywrightTraceUrl = (trace: TraceModel): string | undefined =>
  trace.attachments?.find((a) => a.name === 'trace')?.url;

const deriveVideos = (
  trace: TraceModel,
): Array<{ url: string; label: string }> =>
  (trace.attachments ?? [])
    .filter((a) => a.contentType.toLowerCase().startsWith('video/'))
    .map((a) => ({
      url: a.url,
      label: a.path.split('/').pop()?.toLowerCase() ?? a.name,
    }))
    .sort((a, b) => a.label.localeCompare(b.label));

export const toTracerTest = (
  trace: TraceModel,
  playwrightTestId: string,
): TracerTest => ({
  playwrightTestId,
  attempt: trace.header.context.attempt,
  repoName: 'local',
  statements: trace.statements.map(mapStatement),
  videos: deriveVideos(trace),
  testCase: null,
  triagedVerdict: null,
  finalVerdict: null,
  failure: null,
  playwrightTraceUrl: findPlaywrightTraceUrl(trace),
});
