import { XCircleIcon } from 'lucide-react';

import { cn } from '../../../../lib/utils';

// ─── Types ───────────────────────────────────────────────────

export interface TraceViewerErrorInfo {
  /** Error class name (e.g. "TimeoutError") */
  name?: string;
  /** Short error message displayed in the header */
  message?: string;
  /** Full stack trace string (multi-line). May equal `message` for synthetic errors. */
  stack?: string;
  /** Marks the error as originating from Playwright (renders a badge) */
  isPlaywrightError?: boolean;
}

export interface StackTraceClassNames {
  /** Root wrapper */
  root?: string;
  /** Header row */
  header?: string;
  /** Stack content area (scroll container) */
  content?: string;
  /** Pre-formatted stack body */
  body?: string;
}

export interface TraceViewerStackTraceProps {
  /** Error payload to display */
  error: TraceViewerErrorInfo;
  /** Max height for the stack body (px or CSS value). Default: 300 */
  maxHeight?: number | string;
  /** Style overrides */
  classNames?: StackTraceClassNames;
}

// ─── Helpers ─────────────────────────────────────────────────

const getMaxHeightStyle = (maxHeight: number | string): string => {
  if (typeof maxHeight === 'number') {
    return `${maxHeight}px`;
  }

  return maxHeight;
};

// ─── Component ───────────────────────────────────────────────

export const TraceViewerStackTrace = ({
  error,
  maxHeight = 300,
  classNames,
}: TraceViewerStackTraceProps) => {
  const hasBody = error.stack?.trim() !== error.message?.trim();

  return (
    <div className={cn('overflow-hidden font-mono text-xs', classNames?.root)}>
      {/* Header */}
      <div
        className={cn(
          'flex w-full items-center gap-2 px-3 py-1.5',
          classNames?.header,
        )}
      >
        <XCircleIcon className="size-3.5 shrink-0 text-danger-solid" />

        <span className="shrink-0 font-semibold text-danger-solid">
          {error.name}
        </span>

        <span className="truncate text-muted-foreground">{error.message}</span>

        {error.isPlaywrightError && (
          <span className="ml-auto shrink-0 rounded bg-muted px-1.5 py-0.5 text-[10px] uppercase tracking-wider text-muted-foreground">
            Playwright
          </span>
        )}
      </div>

      {/* Stack body */}
      {hasBody && (
        <div
          className={cn(
            'overflow-auto bg-danger-subtle/30',
            classNames?.content,
          )}
          style={{ maxHeight: getMaxHeightStyle(maxHeight) }}
        >
          <pre
            className={cn(
              'whitespace-pre-wrap break-all px-4 py-3 text-danger-solid',
              classNames?.body,
            )}
          >
            {error.stack}
          </pre>
        </div>
      )}
    </div>
  );
};
