import type { ReactNode } from 'react';

import { cn } from '../../../../../lib/utils';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '../../../../components/select/select';

export interface AttemptOption {
  /** Unique key */
  id: string | number;
  /** Display label (e.g. "Attempt 1") */
  label: string;
  /** Optional tag (e.g. "longest", "latest") */
  tag?: string;
  /** Optional icon */
  icon?: ReactNode;
}

export interface HeaderAttemptSelectorClassNames {
  /** Root wrapper */
  root?: string;
  /** Trigger button */
  trigger?: string;
  /** Dropdown panel */
  dropdown?: string;
  /** Individual option */
  option?: string;
}

export interface HeaderAttemptSelectorProps {
  /** Available attempts */
  options: AttemptOption[];
  /** Currently selected attempt id */
  value: string;
  /** Callback when attempt changes */
  onChange: (id: string) => void;
  /** Summary label (e.g. "Attempt 1/3") */
  label?: string;
  /** Style overrides */
  classNames?: HeaderAttemptSelectorClassNames;
}

export const HeaderAttemptSelector = ({
  options,
  value,
  onChange,
  label,
  classNames,
}: HeaderAttemptSelectorProps) => {
  const selectedOption = options.find((o) => o.id === value);
  const displayLabel = label ?? selectedOption?.label ?? 'Select attempt';

  if (options.length <= 1) {
    return (
      <span className={cn('text-xs text-muted-foreground', classNames?.root)}>
        {displayLabel}
        {selectedOption?.tag && (
          <span className="ml-1 text-muted-foreground/60">
            ({selectedOption.tag})
          </span>
        )}
      </span>
    );
  }

  return (
    <Select value={value} onValueChange={onChange}>
      <SelectTrigger
        size="sm"
        className={cn(
          'h-7 gap-1.5 rounded-md border-0 bg-transparent px-2.5 text-xs hover:bg-muted/40',
          classNames?.trigger,
          classNames?.root,
        )}
      >
        <SelectValue />
      </SelectTrigger>
      <SelectContent className={classNames?.dropdown}>
        {options.map((option) => (
          <SelectItem
            key={option.id}
            value={String(option.id)}
            className={cn('text-xs', classNames?.option)}
          >
            {option.icon && (
              <span className="mr-1.5 shrink-0">{option.icon}</span>
            )}
            {option.label}
            {option.tag && (
              <span className="ml-1.5 text-muted-foreground/60">
                ({option.tag})
              </span>
            )}
          </SelectItem>
        ))}
      </SelectContent>
    </Select>
  );
};
