import {
  CheckCircle2Icon,
  CircleDashedIcon,
  CircleIcon,
  XCircleIcon,
} from 'lucide-react';
import type { ReactNode } from 'react';
import { useMemo } from 'react';

import type {
  VerdictResultStatus,
  VerdictType,
} from '../../verdict-result-indicator/verdict-result-indicator';
import { VerdictResultIndicator } from '../../verdict-result-indicator/verdict-result-indicator';

// ─── Types ──────────────────────────────────────────────────────

export type StepCardVariant =
  | 'danger'
  | 'success'
  | 'warning'
  | 'brand'
  | 'info'
  | 'neutral';

export type StepCardStatus = 'pass' | 'fail' | 'skipped' | 'other';

export type { VerdictType };

export interface StepConfig {
  /** Status/verdict icon as a ReactNode */
  icon: ReactNode;
  /** Resolved color variant */
  variant: StepCardVariant;
  /** Tailwind class for the accent bar (active/selected) */
  accentColor: string;
  /** Tailwind classes for default background + border */
  defaultBg: string;
  /** Tailwind classes for selected background + border */
  selectedBg: string;
}

// ─── Color maps ─────────────────────────────────────────────────

const VARIANT_ACCENT: Record<StepCardVariant, string> = {
  danger: 'bg-danger-solid',
  success: 'bg-success-solid',
  warning: 'bg-warning-solid',
  brand: 'bg-brand-solid',
  info: 'bg-info-solid',
  neutral: 'bg-info-solid',
};

const VARIANT_DEFAULT_BG: Record<StepCardVariant, string> = {
  danger: 'border-danger-solid/10 bg-danger-subtle/30',
  success: 'bg-surface',
  warning: 'bg-surface',
  brand: 'bg-surface',
  info: 'bg-surface',
  neutral: 'bg-surface',
};

const VARIANT_SELECTED: Record<StepCardVariant, string> = {
  danger: 'border-danger-solid/40 bg-danger-subtle',
  success: 'border-success-solid/40 bg-success-subtle',
  warning: 'border-warning-solid/40 bg-warning-subtle',
  brand: 'border-brand-solid/40 bg-brand-subtle',
  info: 'border-info-solid/40 bg-info-subtle',
  neutral: 'border-info-solid/40 bg-info-subtle',
};

// ─── Resolvers ──────────────────────────────────────────────────

const STATUS_TO_VERDICT_STATUS: Record<StepCardStatus, VerdictResultStatus> = {
  pass: 'passed',
  fail: 'failed',
  skipped: 'skipped',
  other: 'pending',
};

const STATUS_ICON: Record<StepCardStatus, ReactNode> = {
  pass: <CheckCircle2Icon className="size-4 text-success-solid" />,
  fail: <XCircleIcon className="size-4 text-danger-solid" />,
  skipped: <CircleDashedIcon className="size-4 text-neutral-solid" />,
  other: <CircleIcon className="size-4 text-neutral-solid" />,
};

export const getStepCardVariant = (
  status?: StepCardStatus,
  verdictType?: VerdictType,
): StepCardVariant => {
  if (verdictType) {
    if (verdictType === 'BUG') {
      return 'danger';
    }
    if (verdictType === 'UI_CHANGED') {
      return 'brand';
    }
    if (verdictType === 'BROKEN_TEST_LOGIC') {
      return 'warning';
    }

    return 'danger';
  }

  if (status === 'fail') {
    return 'danger';
  }
  if (status === 'pass') {
    return 'success';
  }

  return 'neutral';
};

const getStepIcon = (
  status?: StepCardStatus,
  verdictType?: VerdictType,
): ReactNode => {
  if (verdictType && status) {
    return (
      <VerdictResultIndicator
        status={STATUS_TO_VERDICT_STATUS[status]}
        verdictType={verdictType}
        variant="iconOnly"
        size="sm"
      />
    );
  }
  if (status) {
    return STATUS_ICON[status];
  }

  return null;
};

// ─── Hook ───────────────────────────────────────────────────────

export const useStepConfig = ({
  status,
  verdictType,
}: {
  status?: StepCardStatus;
  verdictType?: VerdictType;
}): StepConfig => {
  return useMemo(() => {
    const variant = getStepCardVariant(status, verdictType);

    return {
      icon: getStepIcon(status, verdictType),
      variant,
      accentColor: VARIANT_ACCENT[variant],
      defaultBg: VARIANT_DEFAULT_BG[variant],
      selectedBg: VARIANT_SELECTED[variant],
    };
  }, [status, verdictType]);
};
