import { TraceViewerAutopilotBanner } from '@heal/front-core/ui';

import { useEventProvider } from '../../../../context/event-provider/event-provider.hooks';
import type {
  FinalVerdict,
  TriagedVerdict,
  VerdictPayload,
} from '../../../../types/test';

interface VerdictBodyProps {
  verdict: TriagedVerdict | FinalVerdict;
}

export const VerdictBody = ({ verdict }: VerdictBodyProps) => (
  <div className="flex flex-col gap-3">
    <VerdictPayloadFields payload={verdict.payload} />
    {isFinalVerdict(verdict) && <AutopilotSection verdict={verdict} />}
  </div>
);

const isFinalVerdict = (
  verdict: TriagedVerdict | FinalVerdict,
): verdict is FinalVerdict => 'autopilotFix' in verdict;

const VerdictPayloadFields = ({ payload }: { payload: VerdictPayload }) => {
  switch (payload.type) {
    case 'BUG':
      return (
        <div className="flex flex-col gap-3">
          <Field label="Expected" value={payload.expected} />
          <Field label="Actual" value={payload.actual} />
        </div>
      );
    case 'UI_CHANGED':
      return (
        <UiChangedBody
          description={payload.description}
          screenshots={payload.screenshots ?? []}
        />
      );
    case 'HEAL_SYSTEM_ISSUE':
      return <Field label="Infra issue" value={payload.description} />;
    case 'UNSTABLE_LOCATOR':
      return <Field label="Unstable locator" value={payload.description} />;
    case 'BROKEN_TEST_LOGIC':
      return <Field label="Reason" value={payload.reason} />;
  }
};

const AutopilotSection = ({ verdict }: { verdict: FinalVerdict }) => {
  const { onAutopilotTrigger, isAutopilotPending } = useEventProvider();

  const hasFix = verdict.autopilotFix !== null;

  if (!onAutopilotTrigger && !hasFix) {
    return null;
  }

  const handleTrigger = () => onAutopilotTrigger?.();

  return (
    <TraceViewerAutopilotBanner
      autopilotFix={verdict.autopilotFix}
      isPending={isAutopilotPending ?? false}
      onTrigger={handleTrigger}
    />
  );
};

const UiChangedBody = ({
  description,
  screenshots,
}: {
  description: string;
  screenshots: { before: string; after: string }[];
}) => (
  <div className="flex flex-col gap-3">
    {description && (
      <div className="rounded-md border border-border bg-surface-elevated px-3 py-2 text-sm leading-relaxed whitespace-pre-wrap text-foreground">
        {description}
      </div>
    )}
    <div className="flex flex-col gap-2 w-full">
      {screenshots.map((screenshot, index) => (
        <div className="grid grid-cols-2 gap-2 w-full" key={index}>
          <ScreenShotDisplay url={screenshot.before} />
          <ScreenShotDisplay url={screenshot.after} />
        </div>
      ))}
    </div>
  </div>
);

const ScreenShotDisplay = ({ url }: { url: string }) => {
  if (!url) {
    return null;
  }

  return (
    <div className="flex flex-col gap-1 w-full aspect-square">
      <img src={url} alt="Screenshot" className="w-full h-full object-cover" />
    </div>
  );
};

const Field = ({ label, value }: { label: string; value: string }) => (
  <div className="flex flex-col gap-1">
    <span className="text-xs text-muted-foreground">{label}</span>
    <div className="rounded-md border border-border bg-surface-elevated px-3 py-2 text-sm leading-relaxed whitespace-pre-wrap text-foreground">
      {value}
    </div>
  </div>
);
