import { Allotment } from 'allotment';
import { useCallback, useEffect, useRef, type ReactNode } from 'react';

import { cn } from '../../../../lib/utils';

import 'allotment/dist/style.css';

export interface ViewPane {
  /** Unique identifier for the pane (used as key in layout) */
  id: string;
  /** Content rendered inside the pane */
  content: ReactNode;
  /** Minimum pane size in pixels */
  minSize?: number;
  /** Maximum pane size in pixels */
  maxSize?: number;
  /** Preferred initial size (px or percentage string) */
  preferredSize?: number | string;
  /** Whether the pane is visible */
  visible?: boolean;
}

export interface ViewLayout {
  /** Size of each pane in pixels, keyed by pane id */
  sizes: Record<string, number>;
  /** Visibility of each pane, keyed by pane id */
  visible: Record<string, boolean>;
}

export interface TraceViewerViewClassNames {
  /** Allotment root wrapper */
  root?: string;
  /** Each pane wrapper */
  pane?: string;
}

export interface TraceViewerViewProps {
  /** Array of panes to render */
  panes: ViewPane[];
  /** Split direction */
  direction?: 'horizontal' | 'vertical';
  /** Initial size ratios */
  defaultSizes?: number[];
  /** Show drag separator between panes */
  separator?: boolean;
  /** Callback when layout changes (drag end or visibility change) */
  onLayoutChange?: (layout: ViewLayout) => void;
  /** Override classNames for internal elements */
  classNames?: TraceViewerViewClassNames;
}

const buildVisibilityMap = (panes: ViewPane[]): Record<string, boolean> => {
  const visible: Record<string, boolean> = {};
  panes.forEach((pane) => {
    visible[pane.id] = pane.visible !== false;
  });

  return visible;
};

export const TraceViewerView = ({
  panes,
  direction = 'horizontal',
  defaultSizes,
  separator = true,
  onLayoutChange,
  classNames,
}: TraceViewerViewProps) => {
  const isVertical = direction === 'vertical';
  const lastSizesRef = useRef<Record<string, number>>({});

  // Store onLayoutChange in a ref to avoid re-triggering the visibility
  // useEffect when the callback reference changes (stale closure prevention).
  const onLayoutChangeRef = useRef(onLayoutChange);
  onLayoutChangeRef.current = onLayoutChange;

  const visibilityKey = panes
    .map((p) => `${p.id}:${p.visible !== false}`)
    .join(',');

  useEffect(() => {
    onLayoutChangeRef.current?.({
      sizes: lastSizesRef.current,
      visible: buildVisibilityMap(panes),
    });
  }, [visibilityKey]);

  const handleDragEnd = useCallback(
    (rawSizes: number[]) => {
      const sizes: Record<string, number> = {};
      panes.forEach((pane, index) => {
        if (rawSizes[index] != null) {
          sizes[pane.id] = Math.round(rawSizes[index]);
        }
      });
      lastSizesRef.current = sizes;
      onLayoutChangeRef.current?.({
        sizes,
        visible: buildVisibilityMap(panes),
      });
    },
    [panes],
  );

  return (
    <Allotment
      vertical={isVertical}
      defaultSizes={defaultSizes}
      separator={separator}
      onDragEnd={handleDragEnd}
      className={cn('h-full w-full', classNames?.root)}
    >
      {panes.map((pane) => (
        <Allotment.Pane
          key={pane.id}
          minSize={pane.minSize}
          maxSize={pane.maxSize}
          preferredSize={pane.preferredSize}
          visible={pane.visible}
        >
          <div className={cn('h-full w-full', classNames?.pane)}>
            {pane.content}
          </div>
        </Allotment.Pane>
      ))}
    </Allotment>
  );
};
