import { TraceViewerCodeBlock } from '@heal/front-core/ui';
import { FileTextIcon } from '@phosphor-icons/react';
import { ComponentPropsWithoutRef, useEffect, useRef } from 'react';

import {
  useDataProvider,
  useVerdictStatement,
} from '../../../../context/data-provider/data-provider.hooks';
import { useStatementProvider } from '../../../../context/statement-provider/statement-provider.hooks';
import { useTriageVerdictForm } from '../../../../context/triage-verdict-form-provider/triage-verdict-form-provider.hooks';
import type {
  FinalVerdict,
  Statement,
  StatementStatus,
  TriagedVerdict,
} from '../../../../types/test';
import { flattenStatementsWithIndent } from '../../../../utils/flatten-statements';
import { formatDuration } from '../../../../utils/format-duration';
import { EmptyState } from '../../_components/empty-state';
import { VerdictActionMenu } from '../../_components/verdict-action-menu';

export const CodeView = () => {
  const { currentTest } = useDataProvider();
  const verdictHit = useVerdictStatement();
  const { state } = useTriageVerdictForm();

  if (!currentTest) {
    return (
      <EmptyState
        icon={<FileTextIcon className="h-10 w-10" weight="thin" />}
        message="This test case has no content yet."
      />
    );
  }

  const flattenedStatements = flattenStatementsWithIndent(
    currentTest.statements,
  );

  return (
    <div className="flex h-full flex-1 flex-col overflow-auto bg-background p-2">
      <div className="flex-1 overflow-x-auto py-3">
        <div className="inline-flex w-fit min-w-full flex-col">
          {flattenedStatements.map(({ statement, indent }, index) => (
            <CodeItem
              key={statement.code}
              statement={statement}
              index={index + 1}
              indent={indent}
              verdict={
                verdictHit && verdictHit.statement.id === statement.id
                  ? verdictHit.verdict
                  : null
              }
              isActiveFormStep={
                state.isOpen && state.selectedFailingStatementIndex === index
              }
            />
          ))}
        </div>
      </div>
    </div>
  );
};

function CodeItem({
  statement,
  indent = 0,
  index = 1,
  verdict,
  isActiveFormStep = false,
}: {
  statement: Statement;
  indent?: number;
  index: number;
  verdict: TriagedVerdict | FinalVerdict | null;
  isActiveFormStep?: boolean;
}) {
  const { activeStatement, setActiveStatementId, selectActiveStatement } =
    useStatementProvider();
  const ref = useRef<HTMLDivElement>(null);
  const isActive = activeStatement?.id === statement.id;
  const hasVerdict = verdict !== null;

  useEffect(() => {
    if ((isActive || hasVerdict) && ref.current) {
      ref.current.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    }
  }, [isActive, hasVerdict]);

  if (!statement.code) {
    return null;
  }

  function handleSelectStatement() {
    if (activeStatement?.id === statement.id) {
      setActiveStatementId(null);

      return;
    }

    selectActiveStatement(statement.id);
  }

  return (
    <div ref={ref}>
      <VerdictActionMenu failingStatementIndex={index - 1}>
        <TraceViewerCodeBlock
          key={statement.code}
          status={mapStatementStatusToStepCardStatus(statement.status)}
          verdictType={verdict?.payload.type}
          duration={formatDuration(statement.durationMs)}
          active={activeStatement?.id === statement.id}
          selected={isActiveFormStep}
          onClick={handleSelectStatement}
          code={statement.code ?? ''}
          indent={indent}
          lineNumber={statement.id}
          error={statement.error ?? undefined}
          classNames={{
            gutter:
              'transition-colors group-hover/menu:bg-brand-subtle group-data-[state=open]/menu:bg-brand-subtle-hover',
            root: 'transition-colors group-hover/menu:bg-brand-subtle group-data-[state=open]/menu:bg-brand-subtle-hover',
            code: 'transition-colors group-hover/menu:bg-brand-subtle group-data-[state=open]/menu:bg-brand-subtle-hover',
          }}
        />
      </VerdictActionMenu>
    </div>
  );
}

export const mapStatementStatusToStepCardStatus = (
  status: StatementStatus,
): ComponentPropsWithoutRef<typeof TraceViewerCodeBlock>['status'] => {
  if (status === 'passed') {
    return 'pass';
  }

  return 'fail';
};
