// Wire schema between this SPA and the heal-tracer Node server.
// Server contract is implemented in:
//   heal-playwright-tracer/src/infrastructure/local-viewer-adapter/local-viewer-server.ts
// Keep these types in sync with the server response shapes.

export interface TestSummary {
  /** Compound `${playwrightTestId}_${attempt}` routing key. */
  id: string;
  playwrightTestId: string;
  attempt: number;
  ndjsonPath: string;
  title: string;
  titlePath: string[];
  file: string;
  project: string;
  status:
    | 'passed'
    | 'failed'
    | 'timedOut'
    | 'skipped'
    | 'interrupted'
    | 'unknown';
  duration: number;
  startedAt: number;
}

export interface ExecutionTotals {
  tests: number;
  passed: number;
  failed: number;
  timedOut: number;
  skipped: number;
  interrupted: number;
}

export interface ExecutionSummary {
  executionId: string;
  source?: 'env' | 'generated';
  startedAt?: number;
  endedAt?: number;
  durationMs?: number;
  totals?: ExecutionTotals;
  git?: { sha?: string; branch?: string; dirty?: boolean };
  playwrightVersion?: string;
}

export interface TestEnv {
  nodeVersion?: string;
  platform?: string;
  arch?: string;
  hostname?: string;
  isCI?: boolean;
  cwd?: string;
  gitSha?: string;
  pid?: number;
}

export interface TestContext {
  testId: string;
  attempt: number;
  testCaseId?: number;
  executionId?: string;
}

export interface TestHeader {
  title: string;
  titlePath: string[];
  file: string;
  project: string;
  workerIndex: number;
  retry: number;
  startedAt: number;
  env: TestEnv;
  context: TestContext;
}

export interface StatementErrorCause {
  name?: string;
  message: string;
  stack?: string;
}

export interface StatementError {
  name?: string;
  message: string;
  stack?: string;
  isPlaywrightError?: boolean;
  causes?: StatementErrorCause[];
}

export interface Statement {
  seq: number;
  file: string;
  line: number;
  endLine: number;
  kind: string;
  scope: string;
  source: string;
  hasAwait: boolean;
  leadingComment?: string;
  step: string | null;
  stepPath: string[] | null;
  status: 'ok' | 'threw';
  duration: number;
  t: number;
  pageUrl?: string;
  vars?: Record<string, unknown>;
  error?: StatementError;
  /**
   * Server-rewritten URL for the screenshot. The on-disk filename
   * (e.g. `stmt-0007.png`) is replaced by an absolute path under
   * `/api/screenshot/:id/...` before this reaches the SPA.
   */
  screenshot?: string;
  children: Statement[];
}

export interface TestResult {
  status: 'passed' | 'failed' | 'timedOut' | 'skipped' | 'interrupted';
  duration: number;
  stdout?: string[];
  stderr?: string[];
  error?: StatementError;
}

export interface AttachmentRef {
  /** Server-rewritten URL for the attachment file. */
  url: string;
  /** Playwright's attachment name (e.g. "trace", "video", "screenshot"). */
  name: string;
  /** Path relative to the test's outputDir. */
  path: string;
  /** MIME type. */
  contentType: string;
}

export interface TraceModel {
  header: TestHeader;
  statements: Statement[];
  result?: TestResult;
  /**
   * Full Playwright attachment list (trace.zip, video, screenshots,
   * user attachments). Videos are NOT a separate channel — derive
   * them by filtering on `contentType.startsWith('video/')`.
   */
  attachments?: AttachmentRef[];
}

export interface IndexResponse {
  schemaVersion: number;
  executionId: string;
  tests: TestSummary[];
}

export interface ExecutionsResponse {
  executions: ExecutionSummary[];
}

const handle = async <T>(res: Response): Promise<T> => {
  if (!res.ok) {
    throw new Error(`HTTP ${res.status}: ${res.statusText}`);
  }

  return (await res.json()) as T;
};

export const fetchExecutions = async (): Promise<ExecutionsResponse> =>
  handle<ExecutionsResponse>(await fetch('/api/executions'));

export const fetchIndex = async (executionId: string): Promise<IndexResponse> =>
  handle<IndexResponse>(
    await fetch(
      `/api/executions/${encodeURIComponent(executionId)}/index.json`,
    ),
  );

export const fetchTrace = async (
  executionId: string,
  playwrightTestId: string,
  attempt: number,
): Promise<TraceModel> =>
  handle<TraceModel>(
    await fetch(
      `/api/executions/${encodeURIComponent(executionId)}/tests/${encodeURIComponent(playwrightTestId)}/${attempt}`,
    ),
  );
