import { useEffect, useRef, type ReactNode } from 'react';

import { VideoPlayerControls } from './_components/video-player-controls';
import type { TimelineSegment } from './_components/video-timeline';
import { VideoTimeline } from './_components/video-timeline';
import { useFullscreen } from './_hooks/use-fullscreen';
import {
  DEFAULT_PLAYBACK_RATES,
  REWIND_INTERVAL_MS,
  useVideoController,
  type VideoController,
} from './use-video-controller';

export type {
  SegmentStatus,
  TimelineSegment,
} from './_components/video-timeline';
export type {
  VideoController,
  VideoControllerActions,
  VideoControllerState,
} from './use-video-controller';
export { REWIND_INTERVAL_MS, useVideoController } from './use-video-controller';

export interface TraceViewerVideoPlayerProps {
  /**
   * Optional external controller. When omitted, the player creates its own
   * internal controller — the component remains fully usable standalone.
   */
  controller?: VideoController;
  /** Video source URL */
  src?: string;
  /** Poster image URL */
  poster?: string;
  /** Title displayed above the video (e.g. "REPLAY") */
  title?: ReactNode;
  /** Timeline segments with colored markers */
  segments?: TimelineSegment[];
  /** Currently active segment id (highlighted on timeline) */
  activeSegmentId?: string;
  /** Available playback rates */
  playbackRates?: number[];
}

export const TraceViewerVideoPlayer = ({
  controller: providedController,
  src,
  poster,
  title,
  segments,
  activeSegmentId,
  playbackRates = DEFAULT_PLAYBACK_RATES,
}: TraceViewerVideoPlayerProps) => {
  const fallbackController = useVideoController();
  const controller = providedController ?? fallbackController;
  const { state, actions, videoRef, videoElementProps } = controller;

  const containerRef = useRef<HTMLDivElement>(null);
  const { isFullscreen, toggleFullscreen } = useFullscreen(containerRef);

  const hasSrc = Boolean(src);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      const tag = (e.target as HTMLElement)?.tagName?.toLowerCase();
      if (tag === 'input' || tag === 'textarea' || tag === 'select') {
        return;
      }
      if (e.key === ' ') {
        e.preventDefault();
        actions.togglePlay();
      }
      if (e.key === 'ArrowLeft') {
        e.preventDefault();
        actions.seek(state.currentTimeMs - REWIND_INTERVAL_MS);
      }
    };

    document.addEventListener('keydown', handleKeyDown);

    return () => {
      document.removeEventListener('keydown', handleKeyDown);
    };
  }, [actions, state.currentTimeMs]);

  return (
    <div
      ref={containerRef}
      className="flex h-full w-full flex-col overflow-hidden bg-black"
    >
      {title && (
        <div className="px-4 pt-3 text-xs font-semibold tracking-wider text-white/70">
          {title}
        </div>
      )}

      {/* Video area */}
      <div className="flex min-h-0 flex-1 items-center justify-center">
        {!hasSrc && (
          <span className="text-sm text-white/40">No video available</span>
        )}
        {hasSrc && (
          <video
            ref={videoRef}
            {...videoElementProps}
            src={src}
            poster={poster}
            controls={false}
            onClick={actions.togglePlay}
            onDoubleClick={toggleFullscreen}
            className="h-full w-full object-contain"
          />
        )}
      </div>

      {/* Controls */}
      <VideoPlayerControls
        controller={controller}
        timeline={
          <VideoTimeline
            durationMs={state.durationMs}
            currentTimeMs={state.currentTimeMs}
            bufferedPercent={state.bufferedPercent}
            segments={segments}
            activeSegmentId={activeSegmentId}
            onSeek={actions.seek}
            videoSrc={src}
          />
        }
        isFullscreen={isFullscreen}
        hasSrc={hasSrc}
        playbackRates={playbackRates}
        onToggleFullscreen={toggleFullscreen}
      />
    </div>
  );
};
