import { FileTextIcon } from '@phosphor-icons/react';

import { useCapabilities } from '../../../context/capabilities-provider/capabilities-provider.hooks';
import { useDataProvider } from '../../../context/data-provider/data-provider.hooks';
import { useEventProvider } from '../../../context/event-provider/event-provider.hooks';
import { EmptyState } from '../_components/empty-state';

import { VerdictFormFinalCard } from './_components/verdict-form-final-card';
import { VerdictFormOptions } from './_components/verdict-form-options';
import { VerdictFormResult } from './_components/verdict-form-result';

export const VERDICT_FORM_VIEW_ID = 'verdict-form';

interface VerdictFormViewProps {
  /**
   * When true, render the read-only final-card layout regardless of whether
   * a final verdict exists. Kept as a dev/preview convenience.
   */
  forceReadOnly?: boolean;
}

export const VerdictFormView = ({
  forceReadOnly = false,
}: VerdictFormViewProps = {}) => {
  const { currentTest } = useDataProvider();
  const { onVerdictClassify } = useEventProvider();
  const capabilities = useCapabilities();

  if (!currentTest) {
    return (
      <EmptyState
        icon={<FileTextIcon className="h-10 w-10" weight="thin" />}
        message="No verdict available."
      />
    );
  }

  const { triagedVerdict, finalVerdict } = currentTest;
  const isReadOnly =
    forceReadOnly || !capabilities.canWriteFinalVerdict || finalVerdict != null;

  if (isReadOnly && finalVerdict) {
    return (
      <div className="h-full min-h-0 overflow-auto px-4 py-4">
        <VerdictFormFinalCard verdict={finalVerdict} />
      </div>
    );
  }

  /** Show classify options when a triaged verdict exists and the user can finalize. */
  const showOptions =
    !isReadOnly && triagedVerdict && capabilities.canWriteFinalVerdict;

  return (
    <div className="flex h-full min-h-0 flex-col">
      <div className="min-h-0 flex-1 overflow-auto px-4">
        <VerdictFormResult
          failure={currentTest.failure}
          verdict={triagedVerdict}
        />
      </div>
      {showOptions && (
        <div className="shrink-0 px-4 py-4">
          <VerdictFormOptions
            currentType={triagedVerdict.payload.type}
            onClassify={onVerdictClassify}
          />
        </div>
      )}
    </div>
  );
};
