import type { VerdictType } from '../../../verdict-result-indicator/verdict-result-indicator';
import type {
  SegmentStatus,
  TimelineSegment,
} from '../_components/video-timeline';

const SEGMENT_EDGE: Record<SegmentStatus, string> = {
  pass: 'bg-success-solid',
  fail: 'bg-danger-solid',
  running: 'bg-info-solid',
  pending: 'bg-neutral-solid',
  skipped: 'bg-neutral-solid',
};

const SEGMENT_FILL: Record<SegmentStatus, string> = {
  pass: 'bg-success-subtle hover:bg-success-subtle-hover',
  fail: 'bg-danger-subtle hover:bg-danger-subtle-hover',
  running: 'bg-info-subtle hover:bg-info-subtle-hover',
  pending: 'bg-muted hover:bg-muted-foreground/15',
  skipped: 'bg-muted hover:bg-muted-foreground/15',
};

const SEGMENT_FILL_ACTIVE: Record<SegmentStatus, string> = {
  pass: 'bg-success-subtle-hover',
  fail: 'bg-danger-subtle-hover',
  running: 'bg-info-subtle-hover',
  pending: 'bg-muted-foreground/15',
  skipped: 'bg-muted-foreground/15',
};

const VERDICT_EDGE: Record<VerdictType, string> = {
  BUG: 'bg-danger-solid',
  UI_CHANGED: 'bg-brand-solid',
  HEAL_SYSTEM_ISSUE: 'bg-danger-solid',
  UNSTABLE_LOCATOR: 'bg-danger-solid',
  BROKEN_TEST_LOGIC: 'bg-warning-solid',
};

const VERDICT_FILL: Record<VerdictType, string> = {
  BUG: 'bg-danger-subtle hover:bg-danger-subtle-hover',
  UI_CHANGED: 'bg-brand-subtle hover:bg-brand-subtle-hover',
  HEAL_SYSTEM_ISSUE: 'bg-danger-subtle hover:bg-danger-subtle-hover',
  UNSTABLE_LOCATOR: 'bg-danger-subtle hover:bg-danger-subtle-hover',
  BROKEN_TEST_LOGIC: 'bg-warning-subtle hover:bg-warning-subtle-hover',
};

const VERDICT_FILL_ACTIVE: Record<VerdictType, string> = {
  BUG: 'bg-danger-subtle-hover',
  UI_CHANGED: 'bg-brand-subtle-hover',
  HEAL_SYSTEM_ISSUE: 'bg-danger-subtle-hover',
  UNSTABLE_LOCATOR: 'bg-danger-subtle-hover',
  BROKEN_TEST_LOGIC: 'bg-warning-subtle-hover',
};

export const getSegmentEdgeClass = (segment: TimelineSegment): string => {
  if (segment.verdictType) {
    return VERDICT_EDGE[segment.verdictType];
  }

  return SEGMENT_EDGE[segment.status];
};

export const getSegmentFillClass = (
  segment: TimelineSegment,
  isActive: boolean,
): string => {
  if (segment.verdictType) {
    return isActive
      ? VERDICT_FILL_ACTIVE[segment.verdictType]
      : VERDICT_FILL[segment.verdictType];
  }

  return isActive
    ? SEGMENT_FILL_ACTIVE[segment.status]
    : SEGMENT_FILL[segment.status];
};
